quests[1947] = { id = 1947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey to the Marsh", description = "Now it is time for you to earn your mage's wand.  To begin this quest, speak with the human hermit Tabetha in Dustwallow Marsh.  You will find her shack deep in the marsh, west of Theramore.\n\nSpeak with her, for her knowledge is vast.  You will find Tabetha's cottage west of Theramore, and just north of the Stonemaul Ruins.", sourceObjective = "Speak with Tabetha.Now it is time for you to earn your mage's wand. To begin this quest, speak with the human hermit Tabetha in Dustwallow Marsh. You will find her shack deep in the marsh, west of Theramore.\n\nSpeak with her, for her knowledge is vast. You will find Tabetha's cottage west of Theramore, and just north of the Stonemaul Ruins.", sourceObjectiveStatus = "unverified-source-field" }
quests[1948] = { id = 1948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Items of Power", description = "The building of a mage's wand is not easy.  Rare substances are required, and a vessel must be made that can store great quantities of magical energy.  You must gather these things and bring them to me.\n\nI have written onto this parchment that which you need, and instructions on how to get it.  Bring me exactly what is on this list, and follow my written directions to the letter, for if you do not then when we make your wand things might go... badly.", objectives = "Bring 1 Jade and the Bolt Charged Bramble to Tabetha in Dustwallow Marsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1949] = { id = 1949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hidden Secrets", description = "To make your wand, there are key passages in a certain book that I must read.  The book is called Rituals of Power, written by the Magus Tirth.\n\nI do not have a copy of his book, and none of the world's great libraries possess it.  So you must speak with Tirth and gain it from him.\n\nGood luck.  Tirth used to be a great mage and scholar, but now he spends his time at the gnome and goblin races in the Shimmering Flats, drinking and gambling.", sourceObjective = "Speak with Magus Tirth in the Shimmering Flats.To make your wand, there are key passages in a certain book that I must read. The book is called Rituals of Power, written by the Magus Tirth.\n\nI do not have a copy of his book, and none of the world's great libraries possess it. So you must speak with Tirth and gain it from him.\n\nGood luck. Tirth used to be a great mage and scholar, but now he spends his time at the gnome and goblin races in the Shimmering Flats, drinking and gambling.", sourceObjectiveStatus = "unverified-source-field" }
quests[1950] = { id = 1950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get the Scoop", description = "I can help you with the book, but first you have to help me!\n\nThe tome you seek is in my magically locked strongbox.  To open it a special phrase must be uttered, and I can't remember the phrase!  Normally my assistant helps me remember these things but he's nowhere to be found.\n\nIf you want my book, then find my apprentice!  Ask around the race track--if you're lucky then someone has seen him.  Either drag him back here, or at least get my magic phrase from him so we can open my box!", progress = "What are you waiting for? I need my magic phrase!", objectives = "Find the phrase to Tirth's strongbox, then return to Tirth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1951] = { id = 1951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rituals of Power", description = "Hm... now that I think about it, I don't have my book!  You see, I had some gambling debts and to pay them off I sold the last copy of Rituals of Power to a member of the clergy....\n\nA member of the Scarlet Brotherhood.  He must have taken it to their library in the Scarlet Monastery in Tirisfal Glades!\n\nIf you want that book, then you'll have to go to the monastery to find it.  And sorry about all the trouble.  I'm not myself these days...", objectives = "Bring the book Rituals of Power to Tabetha in Dustwallow Marsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1952] = { id = 1952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mage's Wand", description = "I'll go make the wands now.", sourceObjective = "Speak with Tabetha after her ritual.", sourceObjectiveStatus = "unverified-source-field" }
quests[1953] = { id = 1953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Marsh", description = "It is time, {name}, for you to speak with Tabetha... the hermit of Dustwallow Marsh.  She will instruct you on the creation of a powerful mage's implement.\n\nTabetha's shack lies deep in Dustwallow Marsh, west of Theramore.", objectives = "Speak with Tabetha.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1954] = { id = 1954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Infernal Orb", description = "The first step is to acquire an orb with power.  The warlocks of the Burning Blade have nice, high quality orbs... it's too bad they've bound demons into them!  But we can fix that, yes we can.\n\nGo to Desolace and snatch an infernal orb from a Burning Blade summoner.  You'll find summoners at the Mannoroc Coven.\n\nWhen you have the orb, return to me.", objectives = "Bring an Infernal Orb to Tabetha in Dustwallow Marsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1955] = { id = 1955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Exorcism", description = "Now that we have a summoner's orb, we must exorcise the demon within it.  I can do that.  That's the easy part.\n\nYou're the one who has the hard job.  You're the one who has to kill the demon once it's out.\n\nAnd you'll have to be quick.  If you take too long then he'll jump back in the orb and we'll have to start over!\n\nSo get yourself ready.  Prepare your strongest spells and keep your potions handy, and go get a friend if you have one.  Because this isn't going to be pretty.", objectives = "Kill the Demon of the Orb, then speak with Tabetha.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1956] = { id = 1956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Power in Uldaman", description = "Now that the demon has been removed, we must gain a power source.  Unfortunately, the best power sources are usually the oldest and the hardest to get.  It's neat how fate likes to take a bite out of you sometimes, isn't it?\n\nSo you're going to need to go to Uldaman and defeat the obsidian sentinel there.  He's big, he's tough, and his power source packs a punch!\n\nI wish you the best of luck, {name}.  And if you don't get lucky then, well... it was nice knowing you.", objectives = "Retrieve an Obsidian Power Source and bring it to Tabetha in Dustwallow Marsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1957] = { id = 1957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mana Surges", description = "We are almost finished, but this last step is the most perilous, {name}.\n\nI have the empty summoner's orb and am ready to empower it.  We will do this by harnessing the energy of a mana rift.  I'll cast a spell that will temporarily open a rift, from which creatures, mana surges, will pour out.  You must defeat the mana surges and their power will be released, which I will then collect.\n\nKill enough mana surges before the rift closes and I will place all their collected energy in your orb.", objectives = "Kill 12 Mana Surges in the allowed time limit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1958] = { id = 1958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Celestial Power" }
quests[1959] = { id = 1959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Anastasia", description = "The mages of the Undercity have noted a magical disturbance within the city, and have sent word for mages of the Horde to investigate.\n\nAnastasia Hartwell can tell you more.  Speak with her in the Magic Quarter in the Undercity.", sourceObjective = "Speak with Anastasia Hartwell.The mages of the Undercity have noted a magical disturbance within the city, and have sent word for mages of the Horde to investigate.\n\nAnastasia Hartwell can tell you more. Speak with her in the Magic Quarter in the Undercity.", sourceObjectiveStatus = "unverified-source-field" }
quests[1960] = { id = 1960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Investigate the Alchemist Shop", description = "Algernon's alchemist shop in the Apothecarium is the locus of a strange disturbance.  Invisible creatures, made solely of magic, wander the shop--there must be a reason, and we must find it!\n\nInvestigate the disturbance and capture those creatures.  Take a chest of coffers and a scroll from behind me.  Use the scroll at the shop to make the creatures visible, subdue them with your spells, then throw down a coffer to capture them.  Return with the filled coffers, the empty coffers and the cantation.", objectives = "Obtain a Cantation of Manifestation and a Chest of Containment Coffers from behind Anastasia Hartwell. Bring 3 Filled Containment Coffers, the Chest of Containment Coffers and the Cantation of Manifestation to Anastasia in the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1961] = { id = 1961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering Materials", description = "It is time for you to don your first mage's robes, {name}.  They are a sign of your station, and a testament to your worth.\n\nTo gain the robes, you must gather the mana gems from the Dalaran mages of Silverpine.  Their beliefs are similar to ours and so killing them is somewhat distasteful, but if they lack the strength to resist us, then they do not deserve their lives.\n\nBring the gems and a supply of linen to Josef Gregorian at the Magic Quarter's tailor shop.", objectives = "Bring 10 Linen Cloth and 6 Dalaran Mana Gems to Josef Gregorian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1962] = { id = 1962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spellfire Robes" }
quests[1963] = { id = 1963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shattered Hand", description = "The Warchief is too subtle in his methods. He is cautious to unleash the might of the Horde. Once we were stronger, mighty conquerors all. That pride we must regain, and the Shattered Hand will do so.\n\nWe build strength from the shadows and strike at the exposed, secretly laying our enemies low. A task you must complete for me, to prove your worth.\n\nThe troll Tazan trades with the pirates near Ratchet. He has information I must have. Kill him and bring me his satchel.", objectives = "Kill Tazan and bring his Satchel to Therzok in the Cleft of Shadow in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1978] = { id = 1978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deathstalkers", description = "The Syndicate? I would never have suspected. It seems the lords of Alterac have fallen far in the years since their betrayal.\n\nLord Varimathras will be pleased to learn of this, and as you were so instrumental in this discovery, it would be fitting if you were the one to deliver it to him.\n\nAh, and how could I forget?\n\nWelcome to the Deathstalkers.", objectives = "Deliver Andron's Ledger to Varimathras in the Hall of the Dark Lady in the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1998] = { id = 1998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fenwick Thatros", description = "Lord Varimathras has just sent me a missive about a threat to the Forsaken that must be immediately removed. His name is Fenwick Thatros, one whom Lord Varimathras believes is a leader of the undead that have taken root in Silverpine Forest.\n\nYour name came to mind immediately, {name}. I have faith enough in your abilities that you will carry out this mission flawlessly.\n\nThe latest reports from the Deathstalkers in Silverpine indicate that Thatros can be found near the decrepit dock on Lordamere.", objectives = "Kill Fenwick Thatros and bring his head back to Mennet Carkad in the Rogues' Quarter of the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[1999] = { id = 1999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tools of the Trade", description = "The wizards of the Kirin Tor at Ambermill have stored away important documents pertaining to the current state of Dalaran. This we know from the admissions of one of our prisoners. Lord Varimathras has placed the duty of recovering them in the hands of the Deathstalkers.\n\nThis task falls to you, {name}. You will need some equipment, however, and the knowledge of lockpicking. Speak with Estelle Gendry, our outfitter, and ask her for a set of tools before you set out.", objectives = "Find the Dalaran Status Report and return it to Mennet Carkad in the Rogues' Quarter of the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2000] = { id = 2000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rokar Bladeshadow", description = "Too much idle time for you, {name}. It's time that you learned more of our trade. Just last night, five of our number were found dead in one of the cracks in Orgrimmar, with few leads. There are those that oppose us, using our own methods against us.\n\nSo it is I've decided you should learn the art of lockpicking.\n\nUnfortunately, it is a skill that my hands are not well suited to. You should seek out Rokar, who lives in the hills near Durotar. Even in his old age, I suspect he still has the touch for it.", sourceObjective = "Speak with Rokar Bladeshadow in Durotar.", sourceObjectiveStatus = "unverified-source-field" }
quests[2018] = { id = 2018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rokar's Test", description = "Ah, so now Therzok sends me his budding students, hm? Well, I suppose I can teach you a thing or two. Not that I care much of your business, but I'd not want it on my conscious that I sent you to your death.\n\nBut you must first prove yourself worthy.\n\nI will tell you, {name}. I do not much like this Venture Company. This land reminds me of Draenor, and I do not like the thought of those goblins destroying it. Perhaps if their overseer at the Sludge Fen is killed, their operation will be hamstrung.", objectives = "Kill Overseer Glibby and return his Whistle to Rokar Bladeshadow in Durotar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2019] = { id = 2019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tools of the Trade", description = "Here you go, {name}. These should serve you well. Crafted by my own hand, I swear you'll find none better.\n\nDo not bother to tell me your business, however. I have no interest in Therzok's schemes, I wish only to live out my retirement in peace.\n\nIf you should ever need another set of tools, come back to me, and I will furnish you with a new set. But have a care with them!", objectives = "Return to Therzok in the Cleft of Shadow in Orgrimmar.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2038] = { id = 2038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bingles' Missing Supplies", description = "As if crashing into the Loch wasn't bad enough, troggs from the nearby island attacked me and stole my tools and special Blastenheimer Blastencapper explosives. With no gyrocopter and no explosives, the movement has no chance!\n\nGet my tools back and find my Blastencapper explosives, {name}. For Gnomeregan!", progress = "{name}! Where are my things?!", completion = "You've done the movement a great service, {name}. The troggs and leper gnomes infesting Gnomeregan will soon feel the brunt of a gnomish air assault!", objectives = "Find and return Bingles' supplies:\n\nBingles' Wrench, Bingles' Screwdriver, Bingles' Hammer, and Bingles' Blastencapper.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2039] = { id = 2039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find Bingles", description = "We've lost contact with Bingles! He was sent on a reconnaissance mission over Gnomeregan and hasn't reported back in over a week. I just know he's gone and blown himself up.\n\nHe was last seen flying over the Loch. Perhaps you can investigate, {name}.", completion = "So Gnoarn doesn't trust my reconnaissance abilities? I wonder why...\n\nNevermind that, I need your assistance! Nay! The movement needs your assistance!", objectives = "Find Bingles Blastenheimer in Loch Modan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2040] = { id = 2040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Underground Assault", description = "Gnomeregan has fallen under the control of those dastardly troggs! The situation is grave but perhaps you can help, {name}.\n\nDeep in the Deadmines is a functional goblin shredder. Find that shredder and bring back the intact power supply. With the shredder's power supply, we can give our gyrodrillmatic excavationators the power they need to break through the rocky underground borders of Gnomeregan, opening the way for a gnomish assault!", progress = "Have you found the Gnoam Sprecklesprocket, {name}?", completion = "Well done, {name}. Thanks to you, Gnomeregan is one step closer to its day of liberation!", objectives = "Retrieve the Gnoam Sprecklesprocket from the Deadmines and return it to Shoni the Shilent in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2041] = { id = 2041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak with Shoni", description = "Perhaps... Perhaps you can help us in the battle for Gnomeregan.\n\nIn Stormwind you will find the commander of our underground assault crew, Shoni the Shilent. Shoni needs assistance with her gyrodrillmatic excavationators.\n\nYou will probably find her amongst the dwarves in Stormwind.\n\nGood luck, {name}.", sourceObjective = "Speak with Shoni the Shilent at the Dwarven District in Stormwind.", completion = "Do you bring word from central command?", sourceObjectiveStatus = "unverified-source-field" }
quests[2078] = { id = 2078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gyromast's Revenge", description = "Landlubber, ye needs to find me first mate.\n\nTake this'n key, puts it in his gulliver an' bring him back here to serve the Cap'n.\n\nThem murlocs an' their chief ain't gonna be too happy once me first mate gets a hold of em!", completion = "Yarrr... Ye be provin' yerself to be more than a yella sea dog, landlubber.\n\nThe Cap'n may promote ye to poop deck swabby if ye be keepin' this up...", objectives = "Find Gelkak's First Mate, the Threshwackonator 4100, and lead it back to Gelkak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2098] = { id = 2098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gyromast's Retrieval", description = "A pirate's life ain't an easy one, landlubber. It ain't all about plunderin' and booze! Alas, me ship be sunk just off shore thanks to them pesky Threshadons.\n\nWhat I be needin' is me first mate back in workin' order!\n\nWhen I washed up'n shore, the key for me first mate broke on the rocks and was pilfered by the beasties of Darkshore. Out of the corner of me eyes I saw some of them Ragin' Crawlers, Ferocious Foreststrider, and murloc rummaging through the wreckage....", progress = "Have ye found me broke down key, landlubber?", completion = "Avast ye scurvy sea dog! Ye did it! Soon me first mate be back in workin' order and them beasties won't know what hit em!\n\nHrm, have ye seen me first mate?", objectives = "Find and return the three pieces of Gelkak's Key to Gelkak Gyromast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2118] = { id = 2118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plagued Lands", description = "A sickness spreads across the Darkshore, gripping the minds and bodies of all it touches.\n\nThe Thistle Bears have been hit the hardest by this plague. The once noble beasts are now an instrument of destruction - rabid and frenzied. I may have a cure for this ailment.\n\nTake this trap to the forest and lay it on the ground. Any Rabid Thistle Bear that crosses the light shall become docile for a short time. Once the bear is docile, it shall follow you. Lead it back here, {name}.", completion = "Our work has only just begun, {name}. Are you prepared for your next task?", objectives = "Capture a living Rabid Thistle Bear and bring it back to Tharnariun.\n\nShould you fail to capture a Rabid Thistle Bear and lose your trap, return to Tharnariun Treetender and request another trap.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2138] = { id = 2138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleansing of the Infected", description = "As I had feared, the cure does not work.\n\nIt saddens me greatly to order the death of any of nature's beasts, but the sick and tainted thistle bears must be put down.\n\nReturn to the forest and destroy 20 rabid thistle bears, {name}. It will most certainly not put a stop to the plague but it will slow down the damage the animals are doing to our forest and its inhabitants for a short time.", completion = "You have done Auberdine a great service, {name}, but your task is not yet complete.\n\nReturn to me once you have rested.\n\n...and {name}, prepare your mind and soul for more bloodshed.", objectives = "Cleanse the forest of 20 Rabid Thistle Bears and return to Tharnariun Treetender in Darkshore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2139] = { id = 2139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tharnariun's Hope", description = "The survival of our people and lands comes at unfortunate costs, {name}.\n\nYou have spilled the blood of nature's servants; many sick animals you have felled. The people of Auberdine are indebted to you, for the forest's pain is eased - even if only for a moment.\n\nI have one final task for you, but be warned, you will have to kill again. It is my hope that this will be the last time I call upon you, {name}.\n\nIn a cave to the northeast, near Bashal'Aran, resides the Den Mother. Slay her.", completion = "You have fought for Auberdine with bravery and honor, {name}. In our war torn lands, death and despair are common. Many will not rise to meet the challenge of life in our new home, choosing instead to hide in their homes or escape to the more fortified lands of the Alliance.\n\nThank you, {name}. Perhaps someday soon we shall fight along side as comrades versus another foe.", objectives = "Find and kill the Den Mother.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2158] = { id = 2158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rest and Relaxation", description = "Every adventurer should rest when exhaustion sets in - and there is no finer place to get rest and relaxation than at the Lion's Pride Inn!\n\nMy best friend, Innkeeper Farley, runs the Lion's Pride. If you tell him I sent you, he may give you the special discounted rates on food and drink.\n\nTo find the Lion's Pride Inn, travel south along the road from here -- you can't miss it!", completion = "Rest and relaxation for the tired and cold -- that's our motto! Please, take a seat by the fire and rest your weary bones.\n\nWould you like to try a sampling of some of our fine food and drink?", objectives = "Speak with Innkeeper Farley at the Lion's Pride Inn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2159] = { id = 2159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dolanaar Delivery", description = "Greetings, young {class}.  Can you offer me aid?  I have a package of herbs that I must deliver to the town of Dolanaar.  But I still have business with the druids of Shadowglen and cannot yet leave.\n\nCan you deliver this package for me?  It must be sent to Innkeeper Keldamyr, at the Dolanaar inn.  It lies along the road, to the south.", progress = "How might I be of service to you, young one?  Are you here to rest in the inn?  Do you require a hearthstone?", completion = "Ah yes, the delivery of herbs from Shadowglen.  It is a shame Porthannius could not bring it himself, for we have much to discuss, he and I.  But I am glad to get the herbs nonetheless, and I am glad you came.\n\nWhile you are here, please, rest yourself.  Heroes must keep their strength and spirits high, and must find rest and solace whenever they may.  For to neglect one's peace of body and mind is a sure path to failure.\n\nSo... rest.", objectives = "Bring the Dolanaar Delivery to Innkeeper Keldamyr.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2160] = { id = 2160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplies to Tannok", description = "Hey! You look like a hearty adventurer. If you're planning on braving the pass, do you suppose you could bring a package to the inn in Kharanos?\n\nYou were planning on stopping at the inn, right? If you make it through the pass, you'll definitely want to take a breather there.\n\nAnyways, bring this to Tannok Frosthammer, the innkeeper's assistant. I can't get through the pass myself, and it'll be days until a Mountaineer escort comes through!", progress = "Hi there! Come in, take a seat by the fire and warm yourself with a flagon of ale.", completion = "Ah, at last, the supplies from Hands! I was beginning to worry, we've had scarce word from Anvilmar ever since the troggs overran the pass.\n\nThanks for bringing this to me, {name}. And please, make yourself comfortable. You must be tired after your journey.", objectives = "Deliver the Crate of Inn Supplies to Tannok Frosthammer in Kharanos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2161] = { id = 2161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Peon's Burden", description = "Excuse me?  Can you help me?\n\nI have a load of food here.  I walked along the road and braved scorpids and spiders and worse!  I brought the food to the Valley of Trials because I thought they needed it and I like to help out.  But they don't need any food!  Now I have to take it back to Razor Hill and I'm afraid of all the beasts along the way...\n\nCan you take it for me?  I'm just a peon, but you're a hero.  You fear nothing!\n\nTake it to Innkeeper Grosk at the Razor Hill inn.  Thank you!", progress = "Welcome to Razor Hill!", completion = "Ah, this is the food Ukor brought to the Valley of Trials.  Did they not need it?  Well, I guess they like to starve you heroes in training.  Builds spirit, they say!\n\nThank you for returning the food.  I'll stick it back on the shelves... but here, let me offer you some refreshment first!\n\nAnd don't forget to rest here in the inn.  You may be a brave {class} ready to take on the world, but if your energy is sapped you won't be doing yourself, or the Horde, much good.", objectives = "Bring Ukor's Burden to Innkeeper Grosk in Razor Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2178] = { id = 2178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Easy Strider Living", description = "Do you smell that delicious aroma? It's my secret recipe, {name}--fresh strider stew. Delicious!\n\nPerhaps you would be interested in learning the recipe?\n\nBefore I teach you the recipe, you will need to prove that you can handle the beasts.\n\nNow, I don't expect you to go out and tame one and ride it back to me, but if you can kill a few and bring back some of their succulent meat, I may be persuaded to show you the ways of strider stew.", progress = "The pot is empty and I'm hungry! What's taking you so long?", completion = "Fantastic! Try it and tell me what you think, {name}!", objectives = "Bring back 5 Strider Meat to Alanndarian Nightsong in Auberdine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2198] = { id = 2198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shattered Necklace", description = "You have found a tarnished necklace, though the tarnish belies intricate and magical craftsmanship.  The necklace has been shattered, as its setting appears to be missing three gems.  On the underside of the necklace is the faint imprint of the city seal for Ironforge.  Below the seal are three tiny, engraved letters: \"TdK\".\n\nIf there is anything to be gleaned from the necklace, you will need to learn about its origins.  Perhaps the seal and the initials are a start...", progress = "You've got the wrong gnome, pal!  I was never there!  You can't prove anything!\n\nWait a second... who are you?  What the... where did you find this necklace at?", completion = "Yes... I am the jeweler who made this necklace.  I also am not in the business of handing out information as though it were free.  Information is never free, friend.  If I am going to help you out, you need to help ME out first.", objectives = "Search for the original creator of the shattered necklace to learn of its potential value.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2199] = { id = 2199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lore for a Price", description = "I am a jeweler of great renown here in Ironforge!  Well, former renown anyway... I have fallen onto hard times due to the chicanery of a competitor!  A bad reputation in this business spells financial disaster.  As a result, I find myself without a copper to my good-though-currently-sullied name.\n\nI want you to get me five silver bars to finish an order I received - the first in what seems like an eternity.\n\nYou get me those five silver bars, and I'll answer your questions on the necklace.", progress = "Have you got the five silver bars I asked for?  I will share my sad tale of woe with you concerning the necklace you now possess... but only after I get those bars!  Please, help a gnome out, won't ya?", completion = "You're all right in my book; I don't care what everyone else has been saying... I kid, I kid!  Seriously, thank you my friend.\n\nNow, the necklace you have is one of my finest creations, but it is missing three gems that help bind magic power to it.  I crafted it for a paladin some time ago.  He was on a self-appointed quest to clear out the \"evil taint\" present at an excavation site in the Badlands called Uldaman.\n\nWell... that paladin died in Uldaman, and that was just the beginning of my woes.", objectives = "Bring five silver bars to Talvash del Kissel in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2200] = { id = 2200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to Uldaman", description = "A competitor of mine started a rumor that my necklace cursed the paladin.  Needless to say, no one wants to buy cursed items from a jeweler.\n\n{name}, I'll make you a deal - find the gems and I'll reassemble the necklace, so long as you'll advertise that I do NOT make cursed items!\n\nTry looking for clues in Uldaman; maybe see if the paladin's body is down there, since he's the one who we know had it last!  When you find the gems you should use this; it'll allow you to contact me here in Ironforge.", completion = "Reading the journal reveals that after much effort, the paladin had identified the location of all three missing gems:\n\nThe Shadowforge dwarves hid the ruby in their barricaded area as they battled the Troggs for control of Uldaman.\n\nThe troggs stashed the topaz in an urn located near some unusual inhabitants of Uldaman - Alliance dwarves!\n\nFinally, the trogg elder himself took the sapphire as his own.", objectives = "Search for clues as to the current disposition of Talvash's necklace within Uldaman. The slain paladin he mentioned was the person who had it last.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2201] = { id = 2201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find the Gems", description = "The paladin's journal has provided perhaps the only clues that Uldaman will yield as to the location of the necklace's gems.  If the paladin's scribing remains accurate, then the Shadowforge dwarves and the troggs that vie for control of the dig site will need to be dealt with.\n\nArmed with this knowledge, the search for the gems begins in earnest.  When all the gems have been acquired, Talvash in Ironforge should be notified via the Phial of Scrying as per his instructions.", progress = "Talvash's image comes into focus from the waters of the scrying bowl.\n\n\"Wow, you're still alive!  Did you manage to find the gems?  Are you truly the savior of my reputation I have hoped for?  Please tell me you didn't waste a charge on the phial just to chat; those things are NOT cheap, and I'm already in dire financial straits.\"", completion = "Yep, those indeed are the three gems.  Good job!  Unfortunately, your work isn't quite over just yet.\n\nNo, I'm not trying to pull a fast one here, silly {class}.  This is about making magic jewelry - Talvash del Kissel quality-level jewelry!  You need a strong power source to give it some oomph.  Well, that necklace has no more oomph to give.", objectives = "Find the ruby, sapphire, and topaz that are scattered throughout Uldaman. Once acquired, contact Talvash del Kissel remotely by using the Phial of Scrying he previously gave you.\n\nFrom the journal, you know...\n* The ruby has been stashed in a barricaded Shadowforge area.\n* The topaz has been hidden in an urn in one of the Trogg areas, near some Alliance dwarves.\n\n* The sapphire has been claimed by Grimlok, the trogg leader.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2202] = { id = 2202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uldaman Reagent Run", description = "I've heard about a newly discovered plant called the magenta fungus caps.  They grow in clusters at the Uldaman dig site and can be found in the early tunnels and deep within the less-explored areas.  I want to study their potential use in alchemy, and that's where you come in.\n\nFind the magenta cap clusters and bring me a dozen caps.  Be warned, the clusters may spew out poison spores if jostled.\n\nDo this for me, and I'll whip up a batch of one of my famous restorative elixirs for you!", progress = "Have you obtained the magenta fungus caps I need for my alchemical work?  No caps - no reward!", completion = "Well done {name}, you've proven your worth once again!  The caps will be an interesting study, you betcha.\n\nAnd now, as promised, enjoy a taste of one of my more potent restorative brews from my personal stock...\n\nIf you are a skilled alchemist, then perhaps we might have some additional business to conduct.  Regardless, I thank you for your assistance!", objectives = "Bring 12 Magenta Fungus Caps to Jarkal Mossmeld in Kargath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2203] = { id = 2203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Badlands Reagent Run II", description = "You have been most helpful to me, {class}.  I would reward you with the very recipe for the brew I gave you earlier... but I would ask of you a task that is quite dangerous.  Hear my request.\n\nThis lockbox contains three empty thaumaturgy vessels; they are imbued with an attunement aura that will drain the blood of a scorched guardian dragon.  Using one on the beast will anger it greatly, so be warned.  Once you have all three filled, bring them to me.\n\nDo this, and the recipe will be yours.", objectives = "Use the empty thaumaturgy vessels on scorched guardian dragons found in the Badlands. Once you have them filled, bring them to Jarkal Mossmeld in Kargath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2204] = { id = 2204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restoring the Necklace", description = "You are going to need to find some \"oomph\" for the necklace, and Uldaman is probably the best place for it, actually.  I guess there are a lot of constructs running around in there, yeah?  Well, take out the biggest, baddest construct in that place and grab its power source!  I am pretty sure I can fuse that source into the necklace.\n\nWithout that power source, fixing the necklace will be impossible.  Come back to me here to Ironforge when you have it, and we'll get it all fixed up for you!", progress = "You didn't even stop to tidy yourself up after leaving Uldaman, did you.  You just came straight here, lingering dungeon odors be damned.  Well, let's hope this visit is merely an odiferous one, and not a useless one to boot.\n\nDo you have the power source for the necklace?", completion = "Well I'll be - I sure am glad to see you and this power source in one piece.  It will take me a moment to magically fuse the power source with the necklace now that the gems have been reunited with it.  Once it is done, however, the necklace will be yours!\n\nYou're excited, aren't you?  All tingly with anticipation?  Now where did I put that spell focus at...", objectives = "Obtain a power source from the most powerful construct you can find in Uldaman, and deliver it to Talvash del Kissel in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2205] = { id = 2205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek out SI: 7", description = "The badge? Oh, it's nothing, fish - nothing you could handle anyhow. By the looks of you, I'd say Mathias is likely to mistake you for the cheese delivery <boy/girl> instead of a proper rogue. Regardless, I've been assigned a job and I've made a promise to deliver on that job.\n\nSpeaking of which, deliver this package to Mathias and he may give you a small task or two.\n\nGet cracking.", objectives = "Deliver Keryn Sylvius's package to Master Mathias Shaw at the Stormwind Barracks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2206] = { id = 2206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snatch and Grab", description = "Our operatives in the field are reporting heavy bandit activity south of Goldshire. The reports indicate that bandits have taken over Jerod's Landing and are now using it as a way to smuggle large quantities of contraband from Redridge to Westfall.\n\nI need you to infiltrate the dock house and get me that shipping schedule, {name}. You will probably find it buried deep in the pockets of the Dockmaster.\n\n...and {name}, should you be discovered, SI:7 will disavow all knowledge of your existence.", progress = "Your mortality wanes with every moment you waste loitering in the barracks, {class}.", completion = "I am astonished... Astonished that Keryn finally found a recruit that could possibly have the makings of a proper {class}. Take this blade, {name}. A day will come when you will be called upon again to serve the SI:7. Hone your skills, keep your eyes open and that blade sharp.\n\nYou won't see us coming but you'll feel it when we get there...", objectives = "Find the Dockmaster and recover the Shipping Schedule for Master Mathias Shaw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2218] = { id = 2218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Road to Salvation", description = "Another lost soul looking for guidance, eh? I suppose you want to find a purpose - your purpose. I've seen it a thousand times, another hero looking for work.\n\nWell, today's your lucky day, friend. Hogral's got the cure for your ailment.\n\nHere's what you do: Take this road here up to Ironforge and make your way to the Forlorn Cavern. Once there, locate the thieves' guild and speak with Hulfdan Blackbeard. He'll put you on the road to salvation.", sourceObjective = "Speak with Hulfdan Blackbeard in Ironforge.", sourceObjectiveStatus = "unverified-source-field" }
quests[2238] = { id = 2238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Simple Subterfugin'", description = "Ye see, the King be strip mining the quarry fer ore and gems. More riches than any one dwarf should see in ten lifetimes.\n\nThe Hidden Circle has values, {name}. We value valuables. Can ye understand?\n\nNow we feels the King should be sharing some of that booty, but we don't want ol' 'Stinkbeard' to know he's sharin' - if ye catch me drift.\n\nWe needs ye to speak with Onin MacHammar over by Gnomeregan and bring back a report. The crafty dwarf has hidden hisself amongst the lepers. Be careful.", sourceObjective = "Find Onin MacHammar by Gnomeregan.", sourceObjectiveStatus = "unverified-source-field" }
quests[2239] = { id = 2239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onin's Report", description = "The Quarry? Yap, I see those monstrous armored steam tanks come by this post near every day.\n\nMy contacts to the east tell me that the tank starts off at Ironforge, makes a pickup at the Gol'Bolar Quarry, stops over at Kharanos to refuel and then for some blasted reason, it takes the long way around past Gnomeregan, before reaching Ironforge to drop off the shipment.\n\nIt's all in the report, {race}. Take it back to Hulfdan so he can plan the next step.", objectives = "Take Onin's Report back to Hulfdan in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2240] = { id = 2240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hidden Chamber", description = "Now for the task at hand.\n\nThere is a secret chamber, the Chamber of Khaz'mul, that must be explored.  The problem is that the chamber's behind a huge, locked door!  It's a lucky thing I know how to open it.\n\nI've described everything in my journal, here on the table.  My band and I are stuck here for now... so you, {name}, must find the chamber of Khaz'mul for us!\n\nRead my journal, explore the chamber, then report to Prospector Stormpike at the Explorers' League in Ironforge.", completion = "You have seen the Chamber of Khaz'mul?  Amazing!  Baelog was sure it existed, but I must admit that I had my doubts.\n\nThank you, {name}.  With luck your finding will incite our leaders to renew their efforts to retake Uldaman.  And if it is ever again under Ironforge control, then the secrets of the Chamber of Khaz'mul will be ours!", objectives = "Read Baelog's Journal, explore the hidden chamber, then report to Prospector Stormpike.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2241] = { id = 2241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Apple Falls", description = "They say I'm 'lovestruck,' whatever that means.\n\nSure, I spend my every waking moment thinking about Syurna. Sure, my home is full of paintings and drawings of Syurna. Sure, I often go days without eating, sleeping, or drinking, while I lament about the love we could have had. Is that so wrong?\n\nNow she won't see me! ME! I've tried sending her messages but she won't even talk to another person unless they are a rogue.\n\nCould you deliver this flower to her? Don't forget to tell her it's from Jannok.", objectives = "Take Jannok's Rose to Syurna in Darnassus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2242] = { id = 2242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destiny Calls", description = "We believe there is one being that may be able to help us understand what is happening to the forests of Teldrassil. Unfortunately, getting the creature to cooperate has proven disastrous.\n\nHe hides on a branch at the outskirts of the Oracle Glade. All who have so far approached the satyr, whether through force or diplomacy, have met with doom. Perhaps stealth is the answer, {name}.\n\nFind what Sethir the Ancient carries in his packs and report back to me.", objectives = "Find Sethir the Ancient and bring back any clues that you may discover to Syurna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2258] = { id = 2258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Badlands Reagent Run", description = "{name}, I could use your aid if you're up for it.  I am an alchemist of some note, and I seek your aid in acquiring some reagents found out in the Badlands.\n\nI need the following items to replenish my stocks: five buzzard gizzards, ten crag coyote fangs, and five rock elemental shards.  Obviously, you can get them off of the beasties themselves; if you're not the fighting type, then find friends who are.\n\nAcquire these items for me, you'll get some coin out of the deal.  Watcha wanna do?", progress = "Have you gotten the things I need yet?  You won't get paid unless you bring me those reagents.", completion = "Ah, well done!  These should last me for a little while, at least.  Here is your pay as promised.\n\nIf you're interested, I have some more reagents I could use.  These, however, are only found in the depths of the Uldaman excavation.  They will not be easy to get, but I will make it worth your while if you are interested in helping me again.\n\nPerhaps something more than some shiny coins, yes?", objectives = "Bring 5 Buzzard Gizzards, 10 Crag Coyote Fangs, and  5 Rock Elemental Shards to Jarkal Mossmeld in Kargath, Badlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2259] = { id = 2259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erion Shadewhisper", description = "Do not worry, {name}, I am not sending you to see Syurna. Erion requires your presence at the Cenarion Enclave. Make haste!", sourceObjective = "Contact Erion Shadewhisper in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[2260] = { id = 2260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erion's Behest", description = "Word of your deeds has spread far and wide, {name}. So far, in fact, that Stormwind Intelligence has asked for you by name.\n\nThe journey is taxing and not without peril, but an opportunity to train under SI:7 should not be taken lightly.\n\nA new world awaits you, {name}. Make your way to Old Town in Stormwind and speak with Renzik \"The Shiv\" at SI:7 headquarters.", sourceObjective = "Travel to Stormwind City and seek council with Renzik \"The Shiv.\"", sourceObjectiveStatus = "unverified-source-field" }
quests[2278] = { id = 2278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Platinum Discs", description = "The centerpieces of this treasure chamber are four huge platinum discs, each adorned with numerous sigils of an unknown origin.  Touching them makes your hand tingle.  Just after touching the discs, the visage of a large stone watcher springs forth.\n\n\"Salutations.  I am a keeper of knowledge.  The Creators' synthesis of the Earthen has been chronicled and stored here for this world in the Discs of Norgannon.\"\n\nYou have uncovered a wealth of previously undiscovered worldly lore!", progress = "The voice of the stone watcher seems to resonate within your very inner being:\n\n\"You must first satisfy the data assimilation prerequisite of Discs of Norgannon; once you fulfill this requirement, you will then be permitted to obtain a portable version of the stored data.  Please be sure you have fully explored the information within this repository first.\"", completion = "Following the instructions of the stone watcher, you once again access the Discs of Norgannon now that you have learned about the history of the Earthen, the troggs, and the dwarves.  A faint, brief hum is heard from within the discs.  The stone watcher then speaks:\n\n\"The discs have now been synthesized.  Access the Discs of Norgannon once more to receive your personal copy.\"", objectives = "Speak with stone watcher and learn what ancient lore it keeps. Once you have learned what lore it has to offer, activate the Discs of Norgannon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2279] = { id = 2279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Platinum Discs", description = "Touching the Discs of Norgannon once again makes your hand tingle.  This time, however, a strange grinding noise is heard from inside the discs.\n\nYour backpack suddenly becomes heavier than it was before.  Inside, you discover a miniature version of the discs!\n\nNo doubt, an item of this sort would be invaluable for someone interested in the ancient history of Azeroth.  The Explorers' League in Ironforge is such a group, known throughout the Alliance; perhaps they can make good use of it.", progress = "Yes, may I help you with something?  I assure you I am a very busy right now.  If it is grave importance to the Explorers' League, however, then I am all ears!", completion = "What do you have there... oh my.  You found this where?\n\nNo, really?\n\nYou spoke to whom about what?\n\nNO, REALLY?!\n\nMy fine {class}, you may have just made the archaeological find of the year!  By the Gods who am I kidding, the find of the century!  If these discs are what I think them to be, then this could be the very key we have been looking for!  This may well prove outright once and for all the legitimacy of the Dwarves' enchanted creation!", objectives = "Take the miniature version of the Discs of Norgannon to the Explorers' League in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2280] = { id = 2280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Platinum Discs", description = "Touching the Discs of Norgannon once again makes your hand tingle.  This time, however, a strange grinding noise is heard from inside the discs.\n\nYour backpack suddenly becomes heavier than it was before.  Inside, you discover a miniature version of the discs!\n\nNo doubt, an item of this sort would be invaluable for someone interested in the ancient history of Azeroth.  Someone would sure be interested in this!", progress = "What is that you have there? What did you learn from the discs?", completion = "These discs will change everything. Their secrets are ours now.", objectives = "Take the miniature version of the Discs of Norgannon to someone very interested in them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2281] = { id = 2281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Redridge Rendezvous", description = "Sending you out in the field now would be suicide. Renzik doesn't need another dead rogue on his hands. Don't fret, though, {name} - Renzik is going to get you up to speed.\n\nMake your way to the Redridge Mountains and speak with an associate of SI:7 named Lucius. You will find him hanging around the docks of Lakeshire with the other shady good-for-nothings.", completion = "Ah, so your fingers are a little fat, eh? Don't worry, {name}, I've turned more useless thieves than you into accomplished rogues.", objectives = "Venture forth to Lakeshire in the Redridge Mountains and speak with Lucius.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2282] = { id = 2282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alther's Mill", description = "We've been training thieves here for years! After all, not every rapscallion is born with the grace and finesse of old Lucius.\n\nUp off the road here you'll find Alther's Mill. I got a chest up there with something important inside. Go get it for me! Bring back that token and you'll receive your Certificate of Thievery!", objectives = "Open Lucius's Lockbox, recover the Token of Thievery and return it to Lucius in Lakeshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2283] = { id = 2283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Necklace Recovery", description = "We've got work for you, that is if you've got the guts to do it!\n\nDeep in the Badlands is the Uldaman dig site.  We've heard a tale about some idiot paladin who died there recently.  Why we even care is that he had a very valuable necklace on him.  It's supposedly got three large gems: a ruby, a sapphire, and a topaz.\n\nThe shot: we want it, and we're payin' TOP SILVER to get it.  It may be damaged, but that's neither here nor there; we'll fix whatever scratches are on it.", progress = "Well, do you have the necklace?  You won't see a copper from us if you don't have that necklace!", completion = "Mmmm salvage!  I can smell the necklace from here.  Now let's look at that beauty...\n\nHey, what do you think you're trying to do here?  This necklace is missing the gems!  You think we wouldn't notice?  Even Malton could see that the gems are gone.\n\nWell, maybe you didn't steal them... but this necklace is worthless without those gems!  Your job isn't done here yet, not by a long shot!", objectives = "Look for a valuable necklace within the Uldaman dig site and bring it back to Dran Droffers in Orgrimmar. The necklace may be damaged.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2284] = { id = 2284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Necklace Recovery, Take 2", description = "As sure as Malton is a dummy, those gems are still in Uldaman somewhere.  You're going to have to go back there and look for them.\n\nLike I said before, if the information we have is correct then there's a ruby, a sapphire, and a topaz that go with the necklace.  Find them and put them in the necklace.\n\nAs to where the gems are, who knows?  Maybe you'll get lucky and find the corpse of the Paladin.  If he's not been stripped clean already, then maybe he's got them on him still.", completion = "You seem to have found the remains of the paladin that Dran had mentioned from before.  Searching the remains uncovers what would appear to be his journal.  The book is in poor condition, as dried blood has stained most of the text in the book.  What you can read, however, is gibberish; it is written in the native tongue of the humans, to the best of your knowledge.\n\nYou will need the book translated if you are to glean any knowledge from it.", objectives = "Find a clue as to the gems' whereabouts in the depths of Uldaman.As sure as Malton is a dummy, those gems are still in Uldaman somewhere. You're going to have to go back there and look for them.\n\nLike I said before, if the information we have is correct then there's a ruby, a sapphire, and a topaz that go with the necklace. Find them and put them in the necklace.\n\nAs to where the gems are, who knows?  Maybe you'll get lucky and find the corpse of the Paladin. If he's not been stripped clean already, then maybe he's got them on him still.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2298] = { id = 2298, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kingly Shakedown", description = "So there we were, about to start plottin' out phase III when a couple o' Magni's blockheads come bargin' in here talkin' bout some kind o' heist and arresting some o' the Hidden Circle.\n\nWell nobody puts the iron on old Blackbeard! The argumentations got heavy and thick and somehow yer name weres blurted out!\n\nMe advice? Take the first Gryphon out o' Ironforge and get to Stormwind. Get yerself to Old Town and once there, talk to an old friend o' mine named Renzik \"The Shiv.\"", sourceObjective = "Travel to Stormwind and seek out Renzik \"The Shiv.\"", sourceObjectiveStatus = "unverified-source-field" }
quests[2299] = { id = 2299, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Hulfdan!", description = "Where have you been, {name}? Hulfdan's been looking all over the place for you. We thought the king may have put you in irons.\n\nGet to Ironforge as soon as possible and speak with Hulfdan!", sourceObjective = "Travel to Ironforge and speak with Hulfdan Blackbeard.", sourceObjectiveStatus = "unverified-source-field" }
quests[2300] = { id = 2300, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SI:7", description = "Renzik was looking for you, fish.\n\nI wouldn't keep Mathias's second in command waiting if I were you.", sourceObjective = "Travel to Stormwind and seek out Renzik \"The Shiv.\"", sourceObjectiveStatus = "unverified-source-field" }
quests[2318] = { id = 2318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Translating the Journal", description = "At an impasse of sorts, you know that you will need the book translated into a language you can understand.  There certainly are a number of people in the world who could do it; the closest location that might have someone who could, however, is the Kargath outpost in the Badlands.  Perhaps that is a good place to start.", completion = "Mighty {class}, I know what you are doing out here in the Badlands.  I know you seek my gift of tongues.  You're after the parts to that necklace you found in Uldaman.\n\nSurprised?  Don't be - it's my job to know such things.  Instead, let's discuss what you're going to do for a translated journal.  Trust me - I'm the only one you'll find that can translate it.\n\nBetter still, let me make you a better offer than Dran Droffers is, and it'll let you still complete your deal with them.  Interested now, yes?", objectives = "Find someone who can translate the paladin's journal. The closest location that might have someone is Kargath, in the Badlands.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2338] = { id = 2338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Translating the Journal", description = "Droffers and Son Salvage aren't smart enough to restore the magic in the necklace, but I am.  All I want to do is study the necklace so I can learn to make them myself.  To do that, I will need your necklace.  Let me borrow it, and in exchange for the time I get to study it I will translate the journal for you.  While you are searching for the gems, I should have enough time to learn what I need to.\n\nIt's a simple deal, and no one else will be the wiser.  Whatcha wanna do?", progress = "You've thought about it, yes?  You're a smart {class} if you take this deal - you and I will get what we both want, and Droffers and Son Salvage will think they're getting what they want.", completion = "You know a good deal when you see one - I knew I could count on you.\n\nIt will be just a moment while I cast a spell to quickly translate the human tongue into a form you will understand.  I am a troll of my word; ask anyone in the Horde about Jarkal Mossmeld.  Now, let's get this started...", objectives = "Let Jarkal borrow the necklace. In exchange, he will translate the journal for you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2339] = { id = 2339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find the Gems and Power Source", description = "Here is the journal, translated for you to read on your own.  The crux of it says dwarves hid the ruby, the troggs hid the topaz, and a trogg named Grimlok has the sapphire.\n\nLook - you're going to need a power source to make the necklace work again.  Dran Droffers doesn't know this.  To find one, here's what I'd do: go as deep as you can in Uldaman and kill whatever construct there is the strongest.  No doubt whatever that is would have it.\n\nWhen you have everything collected, come back here!", progress = "You've got another trip into the depths of Uldaman in store for yourself if you don't have the gems and a power source capable of channeling magical power back into the necklace.\n\nYou'll be getting the gems back to deliver to the goons in Orgrimmar; I will be keeping the power source, since it will be the thing that will make the necklace work in the first place...", completion = "Very well done, {class}.  Now the fruits of our redirection will pay themselves out handsomely.  I'm finished with the necklace itself, and I am confident I can duplicate the construction process consistently.\n\nBut first, I will use a specially prepared incantation to quickly analyze those gems before you take them and the necklace back to Orgrimmar.  This will take just a brief moment to do.", objectives = "Recover all three gems and a power source for the necklace from Uldaman, and then bring them to Jarkal Mossmeld in Kargath. Jarkal believes a power source might be found on the strongest construct present in Uldaman.\n\nFrom the journal, you know...\n* The ruby has been stashed in a barricaded Shadowforge area.\n* The topaz has been hidden in an urn in one of the Trogg areas, near some Alliance dwarves.\n* The sapphire has been claimed by Grimlok, the trogg leader.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2340] = { id = 2340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deliver the Gems", description = "Any necklace setting and gem will work, so long as they are the same material.  This power source, however, is what will bring the magic back to the necklace... I hope.\n\nI'll gladly supply the gems needed for your version of the necklace, so long as the power source actually works.\n\nHead to Orgrimmar and keep your end of the bargain with Droffers and Son Salvage.  Just keep your mouth shut about our deal, and when you get back I might have a wonderful surprise for you.", progress = "Well, look who it is!  Took your sweet time getting here, I see.  Let's hope this isn't a waste of my time!  You'll not get paid unless you have everything I asked for.  And trust me on this - we'll be double and triple checking everything!", completion = "Yep, it's all here.  Say, mind if we keep the bag too?  No?  Thanks, appreciate it!  Har!\n\nThis necklace will be our greatest haul yet!  Don't feel too bad though; I'm sure the necklace wouldn't fit you anyway.  Har again!\n\nA deal is a deal, so here's your fee for the salvage.  Our business is done here for now; check back later to see if we have more work.  Until then, beat it!", objectives = "Deliver the Necklace and Gem Salvage to Dran Droffers in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2341] = { id = 2341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Necklace Recovery, Take 3", description = "As Dran and Malton Droffers begin to squabble over their new salvage, half of the deal is now complete.  A trip to the Badlands is now in order to finish things up, as Jarkal Mossmeld in Kargath might have a special reward waiting for you there.", completion = "The power source you gave me exceeded every expectation I had for it.  I was able to make both you and me a necklace, and I have enough left over to make at least three more.  They will fetch quite the fee, with Droffers and Son Salvage none the wiser.\n\nHere you go, my friend.  I give you my thanks on a splendid job... and something quite special for your trouble.", objectives = "Visit Jarkal Mossmeld in Kargath to see if he was successful.As Dran and Malton Droffers begin to squabble over their new salvage, half of the deal is now complete. A trip to the Badlands is now in order to finish things up, as Jarkal Mossmeld in Kargath might have a special reward waiting for you there.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2342] = { id = 2342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaimed Treasures", description = "Sweeping the bat pens with this broom is not befitting a Garrett!  I've earned a little coin from this accursed job, and I'm willing to spend it on you to better my station.\n\nThe Garrett family weapon of choice is locked away in our chest in the South Common Hall of Uldaman from when we Garretts toiled there as diggers.  Without it, I will be stuck here forever - literally - sweeping up after these infernal bats.\n\nReclaim my family's treasure and bring it to me!  Help me restore my birthright!", progress = "The sweeping never ends... these bats are prolific in their mockery of me and my broom.  Please tell me you've reclaimed my family's treasure!  I've offered you my silver - is that not enough?!", completion = "At last - a broom worthy of a Garrett.  You're bloody well worth every silver I spent on you, I say!\n\nDo you hear me, foul bats?  I now wield the Garrett family weapon of choice!  Tremble, bats, tremble!!", objectives = "Get Patrick Garrett's family treasure from their family chest in the South Common Hall of Uldaman, and bring it to him in the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2358] = { id = 2358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Horns of Nez'ra", description = "Many years ago, the Horns of Nez'ra were stolen from Ravenholdt manor. Across continents and oceans I have searched, only to discover that these insignificant beasts have had it in their possession all along.\n\nSlay every Blackrock orc you cross until the Horns of Nez'ra are recovered. Should you recover the horns, find me in Lakeshire.\n\nDo this for me and your name shall be known to Ravenholdt, {name}.", progress = "Do you have the demon prince's horns?", completion = "To deny Ravenholdt the artifact, would be to deny one's own existence. Well done, {class}. You may yet walk among the assassins of Ravenholdt.\n\nAs a young {class} adventuring in Darkshore, I discovered a tea that replenishes energy in combat. It has served me well throughout the years and now I pass on a taste of the thistle tea to you. Drink of it when you tire, {name}, and fight with vigor once more!", objectives = "Return the Horns of Nez'ra to Arantir in Lakeshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2359] = { id = 2359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klaven's Tower", description = "I've been staking out this tower for weeks, {name}. Recently a major shipment came through from Duskwood, and along with it came those guards.\n\nWhat are they? Your guess is as good as mine. I can tell you one thing - they aren't human.\n\nAnyhow, the shipment had a chest - which is what I assume those abominations are guarding. The zombie with the spikes holds a key we'll need.\n\nGet that key, get in the tower, and uncover whatever is in that chest. Take your findings back to Mathias.", objectives = "Steal the Defias Tower Key, break into the Defias Tower and uncover the contents of the Duskwood Chest. Take whatever information you find back to Mathias Shaw in Stormwind. Read Kearnen's Journal to gain insight about the tower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2360] = { id = 2360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mathias and the Defias", description = "Not a moment too soon, {name}. SI:7 reconnaissance is reporting unusually heavy Defias activity in Westfall.\n\nIt would seem that the Defias have taken over an abandoned Alliance watch tower southeast of Sentinel Hill and are using it as a base of operations to smuggle in goods from the Redridge supply route.\n\nGet to Westfall and contact Agent Kearnen for your debriefing. You will find her hidden near the tower.\n\n...and {name}, should you be discovered, SI:7 will disavow all knowledge of your existence.", sourceObjective = "Travel to Westfall and find Agent Kearnen for your debriefing.", sourceObjectiveStatus = "unverified-source-field" }
quests[2361] = { id = 2361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restoring the Necklace", sourceObjective = "I gladly give you this necklace, mighty {class}.  You have done me an invaluable service, and for that I thank you.  Wear it with pride, and make sure you mention loudly and repeatedly who made it for you!\n\nAlso, if you could toss in the fact that it really isn't cursed, that would be great.", sourceObjectiveStatus = "unverified-source-field" }
quests[2378] = { id = 2378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find the Shattered Hand", description = "You have served the Deathstalkers well, {name}, but perhaps it is time for you to venture outward. While you have shown aptitude in the ways of stealth and deception, you still require much training.\n\nThe Deathstalkers have allies within the Shattered Hand. Seek out those that would assist us - find Shenthul in Orgrimmar.", sourceObjective = "Journey to Orgrimmar and speak with Shenthul at the Cleft of Shadow.", sourceObjectiveStatus = "unverified-source-field" }
quests[2379] = { id = 2379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zando'zan", description = "Your determination alone is not enough to overcome the obstacles that lay ahead of us.\n\nSpeak with Zando'zan to begin your training as an operative of the Shattered Hand.\n\nIt is only when you have mastered the practices of stealth and thievery that you may take the next step towards your destiny.", sourceObjective = "Speak with Zando'zan at the Cleft of Shadow.", sourceObjectiveStatus = "unverified-source-field" }
quests[2380] = { id = 2380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Orgrimmar!", description = "A master of stealth and deception you are not, however, all of that can and will change. You've obviously impressed those in charge with your meager skills, as the great Shenthul has asked for you by name.\n\nTake the road north of here to Orgrimmar and speak with Shenthul in the Cleft of Shadow.", sourceObjective = "Speak with Shenthul at the Cleft of Shadow in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[2381] = { id = 2381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plundering the Plunderers", description = "I don't mean to scare you, {name}, but the last five thieves I sent to steal the southsea treasure came back to me in pieces.\n\nSouth along the coast you'll find Tide Razor, the southsea freebooter's ship. Nestled in the hold is the payoff - the southsea treasure. On the second level of that ship is the pirate's den, a place where they train all of their thieves.\n\nBoard that ship, steal the treasure, and bring it back to me. Use the pirate's den if you need to practice your thievery, but be careful!", objectives = "Bring the Southsea Treasure back to Wrenix the Wretched in Ratchet. Do not forget to get an E.C.A.C. and Thieves' Tools from Wrenix's Gizmotronic Apparatus. You will need both of these items to complete your mission.\n\nShould you be attacked by any unusually hostile parrots, use your E.C.A.C.!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2382] = { id = 2382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrenix of Ratchet", description = "Zando'zan has seen it! Yes, the day comes! Thrall's death... the dagger in his back, poison seeping through to his every vein... Zando'zan has said too much.\n\n{name}! Zando'zan has a task for {name}! {name} must travel to Ratchet, east of the Crossroads, and speak with Wrenix the Wretched. Go!", sourceObjective = "Travel to Ratchet in the Barrens and speak with Wrenix the Wretched.", sourceObjectiveStatus = "unverified-source-field" }
quests[2383] = { id = 2383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Simple Parchment", description = "Ah, while you were gone a parchment came for you, {name}.\n\nRead it when you have time. If I'm not mistaken, it came from the warrior trainer Frang. He would have words with you when you're ready. You'll find him outside the Den, taking cover in the shade.", progress = "What's that you have there?  A parchment?  You're not a scholar, I hope...", completion = "Ah, that's my parchment.  I heard you'd be coming to the Valley, {name}.  I'm glad to see you made it--let's hope you survive the trials ahead.", objectives = "Read the Simple Parchment and speak to Frang in the Valley of Trials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2398] = { id = 2398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Dwarves", description = "The dig site at Uldaman wasn't always overrun.  We Ironforge dwarves used to control the area, but... that was before the troggs came.  They came so fast and in such numbers that not even dwarven might could stop them!\n\nIn fact, their attack was so sudden that I fear some of our people may be trapped behind enemy lines.\n\nMy friend Baelog led a small band of dwarves deep within the site just before the troggs showed up.  If he and his company live, then I want you to find them.", completion = "It's about time you showed up!  I was in danger of losing a bet with Olaf!\n\nHe wagered that his beard would grow to his knees before he saw another living {race}.  Well here you are, and as you can see Olaf's beard has a few more inches to go.\n\nThanks, {name}.  I'll split the winnings with you.", objectives = "Find Baelog in Uldaman.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2399] = { id = 2399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sprouted Fronds", objectives = "The fronds Denalan planted within his garden have sprouted and grown.  They tremble, eager to be picked....", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2418] = { id = 2418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Power Stones", description = "A while ago, I had an incident with the Shadowforge Dwarves.  They brought me to Angor Fortress to study two types of strange stones from Uldaman.  I discovered that the stones were sustained, stable power sources if treated correctly.  It's amazing the things one can find in that old dig site!\n\nAnyway, after I told them the secret of the stones they kicked me out of Angor Fortress and began digging for more in Uldaman.\n\nI want those stones for myself!  Bring me both types and I'll pay you plenty!", progress = "Do you have the power stones, {name}?  I have a robotic rodent that needs a power supply...", completion = "That's great, you found some!  Thanks a lot, {name}.  You're the most dependable {race} I've met!\n\nI can't wait to try these on some devices I've been tinkering with.  I bet that, under the right circumstances, devices powered with these stones will keep going, and going, and going...", objectives = "Bring 8 Dentrium Power Stones and 8 An'Alleum Power Stones to Rigglefuzz in the Badlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2438] = { id = 2438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Emerald Dreamcatcher", description = "I was once given an emerald dreamcatcher from Gaerolas Talvethen, the warden of the druids in the Ban'ethil Barrow Den. This powerful amulet is able to siphon energy from the Emerald Dream, bestowing luck upon those who carry it.\n\nSadly, I have not been able to retrieve it from my dresser in Starbreeze Village... Although Starbreeze was once a tranquil place, it has now succumbed to the corruption of the furbolg that reside there.\n\nPerhaps you would be willing to recover my dreamcatcher, {class}?", progress = "Please move swiftly. I can only hope that my emerald dreamcatcher has been unharmed by the furbolg.\n\nHave you recovered it yet, {name}?", completion = "My emerald dreamcatcher is of great importance to me. It is a gift only given to few. Thank you for returning it, {name}.", objectives = "Retrieve the Emerald Dreamcatcher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2439] = { id = 2439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Platinum Discs", description = "This object is an incredible find.  The ancient Titans, or the Creators as these discs refer to them as, are the link to our enchanted creation, if the lore stored in here is correct!  We'll need to invest as much research time into this as possible.\n\nAs for you, heroic {class}, take this voucher to Dinita Stonemantle at the vault.  It grants you what I think is a fitting for such a tremendous find!\n\nReturn to me directly when you are ready; there is much more to do for the Explorers' League!", progress = "Welcome to the Vault of Ironforge, {name}.  What may I do for you today?", completion = "As yes, a voucher from the Explorers' League... and quite the valuable one, might I add.\n\nThe Explorers' League lends me the authority to offer you a choice in your compensation directly from their vault.  You are to receive this item, and you may choose between five superior healing potions or five greater mana potions as your reward.", objectives = "Take your reward voucher to Dinita Stonemantle in the Vault of Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2440] = { id = 2440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Platinum Discs", description = "I shall focus my energies on these discs; they will reveal their true workings to me in due time.\n\nAs for you {name}, I will now reward you for your diligence in bringing this to my attention.  Take this voucher to Bena Winterhoof, the alchemy trainer for Thunder Bluff.  She will give you a special item I believe you will find appealing, and she will supply you with a choice of potions from my personal stock.\n\nReturn to me soon, as I sense there is much more at hand for us to do regarding this find.", progress = "Greetings, {class}!  Are you here for alchemy training, or perhaps something else?", completion = "Well {name}, you must have pleased Sage Truthseeker greatly for him to give you this item.  You are also to be granted a gift from his cache of potions; you may choose between 5 superior healing potions or 5 greater mana potions as your reward.", objectives = "Take the reward voucher to Bena Winterhoof in Thunder Bluff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2458] = { id = 2458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deep Cover", description = "The Venture Company... Perhaps you have heard of them?\n\nFor one year we have worked on planting an agent deep within their ranks. Through much hard work and careful planning, we succeeded.\n\nRecently we received word that the Venture Co. are planning something on a grand scale. Go north of the Sludge Fen to the Venture Co. tower and contact our undercover agent, Taskmaster Fizzule.\n\nWhen you find the tower, use this flare gun, then approach Fizzule and show him the salute of the Shattered Hand.", objectives = "Travel to the Venture Co. Tower, north of the Sludge Fen and contact the Shattered Hand's covert operative, Taskmaster Fizzule.\n\nWhen the tower is in sight, use the Flare Gun to signal your arrival to Taskmaster Fizzule. Fire off TWO flares, then approach Taskmaster Fizzule and perform the Shattered /Salute.\n\nThese actions must be performed in the correct order, as Fizzule will attack and terminate any person he does not recognize.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2459] = { id = 2459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ferocitas the Dream Eater", description = "The emerald... It is missing! My dreamcatcher has been damaged!\n\nThere is a band of Gnarlpine mystics located to the north of Starbreeze. I have heard reports that their leader, Ferocitas the Dream Eater, has been wearing a necklace that glows green in the night. Now seeing my dreamcatcher, I am sure that he has stolen my emerald... He would never realize that its power is useless to him.\n\nFind this missing jewel, {name}. And, while you're there, clear out some of the corrupted mystics as well.", progress = "Ferocitas and the Gnarlpine mystics must return what is mine.  Please retrieve the emerald so that I may repair my emerald dreamcatcher.", completion = "Now I can repair my dreamcatcher.  Thank you, {name}.", objectives = "Kill 7 Gnarlpine Mystics and find the missing jewel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2460] = { id = 2460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shattered Salute", description = "As a rogue of the Shattered Hand, it is imperative that you learn the Shattered Salute. It is the only way to truly identify another member of the Hand.\n\nWatch, learn, repeat.", objectives = "Perform the Shattered Salute on Shenthul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2478] = { id = 2478, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Possible But Not Probable", description = "You will need to steal the tower key from Foreman Silixiz, {name}. Once you've got the key in your possession, hold on to it - I may need it later.\n\nRemember, the poison has weakened everything in this tower. Use your abilities to bring chaos and destruction to its inhabitants. Slay them all -- show no mercy!\n\nOnce everything inside lays in a bloodied heap, pick Gallywix's lockbox and steal the cache of Zanzil's mixture held inside. Take both the head of Gallywix and the mixture to Shenthul in Orgrimmar.", objectives = "Steal Silixiz's Tower Key from Foreman Silixiz, then kill two Mutated Venture Co. Drones, two Venture Co. Patrollers, and two Venture Co. Lookouts.\n\nAssassinate Grand Foreman Gallywix and take his head, then pick the lock on Gallywix's lockbox and steal the Cache of Zanzil's Altered Mixture. Take the Cache and Gallywix's Head back to Shenthul in Orgrimmar for further instruction.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2479] = { id = 2479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinott's Assistance", description = "Take a sample of the mixture to Serge Hinott in Tarren Mill.\n\nIf anyone can cure you, it's Serge. Live long enough and Serge will show you the ways of poison creation and use.", objectives = "Travel to Tarren Mill in Hillsbrad Foothills and deliver the Sample of Zanzil's Mixture to Serge Hinott.\n\nTo get to Tarren Mill, take the Zeppelin to the Undercity and follow the road south through Silverpine and towards Hillsbrad. Follow the signs!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2480] = { id = 2480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinott's Assistance", description = "I have never seen such wondrous results from a poison! Zanzil you say? Never heard of him, however, I must commend him on the creation of this concoction.\n\nSo, I am to cure you of this and then teach you how to make use of the poison?\n\nGive me a few moments to examine the toxin, {name}.", objectives = "Wait for Serge Hinott to complete the cure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2498] = { id = 2498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Denalan", description = "I have just received word that  Denalan at Lake Al'Ameth has discovered what may be the cause of the tumors that plague the timberlings. Please speak with him, and tell him I sent you.\n\nMake haste, {name}; he needs our help.", sourceObjective = "Rellian Greenspyre wants you to speak with Denalan at Lake Al'Ameth.", completion = "Ah, so Rellian sent you to aid me. I am glad you arrived here so soon.\n\nI have discovered something quite disturbing!", sourceObjectiveStatus = "unverified-source-field" }
quests[2499] = { id = 2499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oakenscowl", description = "I figured it out! I had to rush here to find you! It's so simple really... the corruption has spread from timberling to timberling, but there's but one that is the source.\n\nOakenscowl, he's being poisoned by the largest tumor I have ever seen... I would call it gargantuan, even.\n\nOakenscowl used to reside in a cave near my lake, but has since found his way to a nook to the northeast of here. {name}, Hunt down Oakenscowl and collect the tumor; remove this source of corruption from my home.", progress = "Have you located Oakenscowl yet, {race}?", completion = "I knew you were more than capable of ridding the lake of that horrible beast.\n\nIt is a distressing situation; Oakenscowl was once a grand leader amongst his kind... but corruption does not discriminate between the lowly and the noble.\n\nThe size of this tumor is quite disturbing, but I must study it to learn more about the disease that upsets the timberling population.\n\nThank you, {name}.", objectives = "Collect the Gargantuan Tumor from Oakenscowl.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2500] = { id = 2500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Badlands Reagent Run", description = "{class}, I would make use of your services.  I am an alchemist of some note, and I seek your aid in acquiring some reagents found out in the Badlands.\n\nI need the following items to replenish my stocks: five buzzard gizzards, ten crag coyote fangs, and five rock elemental shards.  Obviously, you can get them off of the beasties themselves; if you're not the fighting type, then find friends who are.\n\nAcquire these items for me, you'll get some coin out of the deal.\n\nWell, what say ye?", progress = "Have you gotten the things I need yet?  You won't get paid unless you bring me those reagents.", completion = "Ah, well done {name}.  These should last me for a little while at least.  Here is your pay, as promised.\n\nIf you're interested, I have some more reagents I could use.  These, however, are only found in the depths of the Uldaman excavation.  They will not be easy to get, but I will make it worth your while if you are interested in helping me again.\n\nPerhaps something more than some shiny coins, yes?", objectives = "Acquire the reagents Ghak Healtouch needs from the Badlands, then return to him in Thelsamar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2501] = { id = 2501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Badlands Reagent Run II", description = "You have been most helpful to me, {name}.  I would like to reward you with the very recipe for the brew I gave you earlier, but I must ask of you a favor that is quite dangerous.\n\nThis lockbox contains three empty thaumaturgy vessels; they are imbued with an attunement aura that will drain the blood of a scorched guardian dragon.  Using one on the beast will anger it greatly, so be careful.  Once you have all three filled, bring them to me.\n\nDo this, and the recipe will be yours.", progress = "Have you used the vessels to get me the scorched guardian dragon blood I need?  Yes, I know it is a dangerous task... but the recipe for my restorative brew awaits your success.  Risk and reward, my friend... risk and reward...", completion = "From one alchemist to another, I salute you.  Here, take this recipe and commit it to your knowledge.  May it bring you the success and rewards that it has brought me over the years!", objectives = "Use the empty thaumaturgy vessels on scorched guardian dragons found in the Badlands. Once you have them filled, bring them to Ghak Healtouch in Thelsamar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2518] = { id = 2518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tears of the Moon", description = "Lady Sathrah was once beloved of Elune. Graceful and pure, the spider spun her silver threads through the moonlight, catching the evening mist. The silvery dew had strong healing powers and was kept at the nearby temple.\n\nBut of late, Sathrah has descended into madness. Her future generations are now threatened as well.\n\nFind Lady Sathrah, {name}, and end her suffering. She dwells northeast of here, near the river. Gather her silvery spinnerets and bring them back to me.", progress = "I regret the task that I have asked you to carry out; but Lady Sathrah is beyond hope.\n\nIt is our hope to offer the sacrifice of the spinnerets to Elune. With this sacrifice, Elune will bless Sathrah so that she might be reborn, and at peace.", completion = "The forest mourns for Lady Sathrah, but it was something that had to be done. I hope now that she can rest in peace.\n\nThank you, {name}.", objectives = "Recover Lady Sathrah's Silvery Spinnerets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2519] = { id = 2519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Temple of the Moon", description = "A once great creature of the forest is in need of help, {race}.\n\nThere is a difficult task that must be done.\n\nPlease seek out Priestess A'moora; she will explain things to you. Find her to the southeast of here, inside the Temple of the Moon.", sourceObjective = "Sister Aquinne wants you to speak with Priestess A'moora in the Temple of the Moon.", completion = "So, Sister Aquinne sent you?", sourceObjectiveStatus = "unverified-source-field" }
quests[2520] = { id = 2520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sathrah's Sacrifice", description = "Now you must finish the task to which you have been appointed. Take the spinnerets and offer Lady Sathrah's sacrifice to Elune; lay the great spider to rest.\n\nInside this temple, find the central fountain. There is where you may leave the sacrifice.  The holy waters will purify and cleanse the corruption that drove Sathrah mad.\n\nWhen you have completed this, return to me.", completion = "The loss of Lady Sathrah is distressing, but in this way only may she be reborn with a renewed spirit.\n\nMay Elune willingly accept the sacrifice that you have offered her.", objectives = "Priestess A'moora wants you to place Lady Sathrah's silvery spinnerets at the fountain inside the temple, and then return to her.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2521] = { id = 2521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Serve Kum'isha", description = "{race}, can your miniscule brain comprehend the rarity of a flawless sphere of draenethyst? Draenei have spent lifetimes in search of just one of these crystals, only to meet horrible fates, their purpose unfulfilled.\n\nSo you stand before Kum'isha, knowing what Kum'isha has requested and still wish to assist? Very well, {race}... At any time during your travels across these lands, should you find a flawless sphere of draenethyst, return it to me and I shall reward you with riches beyond your wildest dreams.", progress = "I have dedicated my life to the search of flawless draenethyst spheres. A lifetime, {race}!", completion = "Do my eyes deceive me? Impossible! Where did you... How...\n\nPerhaps now a rift can be opened, returning us to our homeland.", objectives = "In your journeys throughout the Blasted Lands, should you ever come across a Flawless Draenethyst Sphere, take the item back to Kum'isha the Collector.\n\nBe warned, this gem is one of the most rare crystals in all of Azeroth. Any creature in these lands could be holding a Flawless Draenethyst Sphere.\n\nYou will be rewarded for each Flawless Draenethyst Sphere you have collected.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2522] = { id = 2522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kum'isha's Endeavors", description = "Even though the portal conjuration was a failure, I remain hopeful that my next attempt will be successful.\n\nThe hope of the Draenei is as fervent as your greed for trinkets, {race}. Go back out into these cursed lands and recover another flawless draenethyst sphere.\n\nOf course, the choice to take on this task is completely left to you *grin*.", progress = "Have you found another flawless draenethyst sphere?", completion = "Simply amazing. I had doubted that you could find another sphere, yet here it is, pulsating in my hands.\n\nWell done, {name}!\n\nShould you find anymore--and I believe this to be an impossibility--return them to me and I shall reward you again.", objectives = "Find and return a Flawless Draenethyst Sphere to Kum'isha the Collector.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2523] = { id = 2523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupted Songflower", progress = "You have found a sickly, corrupted version of what appears to be a songflower plant. A pungent, unhealthy odor emanates from the plant. It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply some Cenarion plant salve to the songflower. It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
quests[2541] = { id = 2541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sleeping Druid", description = "The Gnarlpine shaman that inhabit this place have discovered a way of separating a sleeping druid's spirit from the physical body. The furbolg have animated my physical form and are using it to attack anyone that attempts to explore the Ban'ethil Barrow Den. I am now trapped in the Emerald Dream, powerless to stop this.\n\nYou must help me. The Gnarlpine shaman carry a strange charm which is used to perform this ritual, and I'd like to examine it. Please, {name}, bring one to me.", progress = "If I can examine the charm, I may be able to figure out how to break the enchantment. Have you found one?", completion = "Thank you, {name}.\n\nWhat an odd trinket this is... I can sense the vile aura emanating from it; this is a very powerful enchantment.", objectives = "Bring a Shaman Voodoo Charm to Oben Rageclaw in the Ban'ethil Barrow Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2561] = { id = 2561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Druid of the Claw", description = "After examining this charm, {name}, I see now what must be done. Please take it, and do as I ask.\n\nYou are to approach the door to the nearby chamber. Inside, you will find my soulless body... Although I regret what I am about to tell you, I see no other way to free myself from the control of the Gnarlpine.\n\nIn order for me to escape them, you must kill my physical form.  Once that is done, use the voodoo charm on my fallen body. After you have completed this task, please return to me.", progress = "{name}, be wary when approaching my physical form; the enchantment it is under is quite powerful.", completion = "I am finally free of the control of the Gnarlpine. Thank you, {name}.\n\nMy spirit may now rest peacefully forever in the Emerald Dream.\n\nPerhaps one day we may meet again, young {class}. But, for now, please accept this reward as a symbol of my gratitude.", objectives = "Kill the soulless body of Oben Rageclaw, and then use the Voodoo Charm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2581] = { id = 2581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snickerfang Jowls", description = "It is a well known fact that hyenas possess tremendous strength in their jowls, but the strength to snap through three inches of thorium steel? Impossible, improbable, and yet I have seen this demonstrated with my own eyes.\n\nVenture forth, into the Blasted Lands, and bring me three snickerfang jowls. As you search for the snickerfang, be on the lookout for boars and scorpoks: The initial assay also requires two blasted boar lungs and one scorpok pincer to complete.", progress = "You smell foul, {name}. Have you been traipsing in sulfur fields? And where are my components?!", completion = "How do you feel, {name}? You radiate with the aura of the snickerfang--your strength, unmatched by mortals!\n\nUnfortunately, with the components you brought to me, I could only make enough of the assay for one tablet. I will require more components, should you require another tablet.", objectives = "Bring three Snickerfang Jowls, two Blasted Boar Lungs, and one Scorpok Pincer to Bloodmage Drazial.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2582] = { id = 2582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rage of Ages", description = "Ah, {name}, welcome back. It seems you enjoyed the effect of the robust, operational imbue, derived from snickerfang. Be warned, while the immediate effect is a titanic burst of strength, the long term effects on your spirit and intelligence could be hazardous.\n\nWith that said, do you require more? If so, bring me another three snickerfang jowls, two blasted boar lungs, and one scorpok pincer.", progress = "Do you have the beast organs?", completion = "There you go! Remember, use it sparingly. If you require another, come see me after you finish the one you currently have in your possession.", objectives = "Bring three Snickerfang Jowls, two Blasted Boar Lungs, and one Scorpok Pincer to Bloodmage Drazial.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2583] = { id = 2583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Boar's Vitality", description = "Within these blasted lands exists two species of boar: the ash-mane boar and the helboar.\n\nIt would appear that the stamina of these beasts renders them nearly immune to harm, as the other animals find them too difficult to kill and consequently, not worth the effort.\n\nWe need to perform further analysis, {name}. Should you bring me three blasted boar lungs, two scorpok pincers, and one basilisk brain, I shall create a divine elixir from the residue of the assay. You will be my first test subject!", progress = "Where are the organs, {name}!?", completion = "The spirit of the boar illuminates your being, {name}! I wonder, do you believe yourself to be as invulnerable as these beasts?", objectives = "Bring three Blasted Boar Lungs, two Scorpok Pincers, and one Basilisk Brain to Bloodmage Drazial.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2584] = { id = 2584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirit of the Boar", description = "When I first administered the elixir, {name}, I could tell that one or two applications would not satiate your appetite. Even now, I can see the hunger in your eyes. The concoction has addictive properties of which, seemingly, the most strong of will cannot resist.\n\nSo be it! Should you require more of the lung juice cocktail, venture back into the wasteland and find for me three blasted boar lungs, two scorpok pincers, and one basilisk brain.", progress = "Where are the organs, {name}!?", completion = "I must warn you, {name}, do not attempt to mix the formulas I have created. The chemical properties of the formula you most recently ingested will always take precedence over former enchantments; thus, rendering the other formulation null.", objectives = "Bring three Blasted Boar Lungs, two Scorpok Pincers, and one Basilisk Brain to Bloodmage Drazial.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2585] = { id = 2585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Decisive Striker", description = "Have you ever watched them in battle, {name}? The scorpoks, I mean. Have you ever seen the grace and agility with which they move? The decisiveness of their strikes?\n\nIf only we could somehow isolate that agility and encapsulate it, we would be wealthy beyond our... I mean... it would be a boon for the scientific community.\n\nAssist me, {name}, and I shall allow you a sampling of the assay.\n\nIn order to create a stable sample, I will need three scorpok pincers, two vulture gizzards, and one blasted boar lung.", progress = "Where are the organs, {name}!?", completion = "Fascinating. This has been the most difficult of all assays to analyze.\n\nTake a pinch of this residual salt and place it under your tongue. You should experience a slight feeling of euphoria followed by a state of unprecedented agility and quickness.", objectives = "Bring three Scorpok Pincers, two Vulture Gizzards, and one Blasted Boar Lung to Bloodmage Drazial.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2586] = { id = 2586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salt of the Scorpok", description = "You live! This is good news, indeed. I assume you are back for more of the scorpok assay?\n\nVery well, {name}, back to the wasteland with you and do not return until you have collected three scorpok pincers, two vulture gizzards, and one blasted boar lung.", progress = "Where are the organs, {name}!?", completion = "Fine work, {name}. Here is one sample of the assay for you and the remaining nine will be used in my research.\n\nAnytime you require more of the ground scorpok assay, return to me and we shall work out a deal.", objectives = "Bring three Scorpok Pincers, two Vulture Gizzards, and one Blasted Boar Lung to Bloodmage Drazial.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2601] = { id = 2601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Basilisk's Bite", description = "These wastelands are riddled with redstone basilisk, {name}. These basilisk have adapted and flourished, more so than any of the other wildlife within the region.\n\nI have watched from afar as they hunt and go about their daily activities - the beasts exhibit a thought process more complex than even some humanoids.\n\nI must study their brains!\n\nRetrieve ten of their brains for me, {name}. The compound cannot be complete, however, without two vulture gizzards to form the base of the solution.", progress = "Have you returned with the requested organs?", completion = "This is wondrous, {name}! My offering to you is a taste of the inner workings of the redstone basilisk.\n\nShould the compound be to your liking, more can always be made... for a price.", objectives = "Bring ten Basilisk Brains and two Vulture Gizzards to Bloodmage Lynnore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2602] = { id = 2602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infallible Mind", description = "Your focused concentration has dwindled so soon? More research must be done!\n\nOh yes, the price remains the same, {name}. Venture forth into the blasted lands and return to me with ten brains from the redstone and two vulture gizzards.", progress = "Have you returned with the requested organs?", completion = "Yes, yes, give me a moment and more of the compound will be ready for your consumption, {name}.\n\nTake it... and {name}, do not attempt to consume these experimental concoctions in rapid succession. The results could be disastrous.", objectives = "Bring ten Basilisk Brains and two Vulture Gizzards to Bloodmage Lynnore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2603] = { id = 2603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vulture's Vigor", description = "Death does indeed have wings in these blasted lands, {race}. I have witnessed the black slayers and bonepickers feasting upon the corpse of many a fallen explorer - sometimes feeding upon the most vile and disease ridden of carcasses. It is a wonder, then, how their internal systems overcome the pestilence that claims these lands.\n\nAssist me in my studies, {name}! Gizzards I need! Two snickerfang jowls will also be required for the base of the concoction.\n\nYou shall be rewarded two-fold for your efforts.", progress = "Do not waste my time, {name}. We have nothing to discuss, unless you have recovered the items I have requested.", completion = "Most excellent! I shall get to work immediately. Perhaps a cure for many of the ailments of the world is to be found!\n\nAh yes, your reward - of course, should you require more of the gum, return to me and another task you shall be given.", objectives = "Bring ten Vulture Gizzards and two Snickerfang Jowls to Bloodmage Lynnore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2604] = { id = 2604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiritual Domination", description = "I see that the inner fire has dwindled. Would you say the spiritual euphoria lasted an hour?\n\nIf it's more of the gizzard gum you desire, then more of the gizzards I require. Back to the wastelands, {name}. Do not return until you have recovered ten gizzards and two jowls.", progress = "Do not waste my time, {name}. We have nothing to discuss, unless you have recovered the items I have requested.", completion = "Perhaps one day I shall be able to isolate the active enzymes of this assay and produce a much more efficient resultant. Unfortunately, you will have to settle for what I am currently able to produce. Return to me should you require more gizzard gum.", objectives = "Bring ten Vulture Gizzards and two Snickerfang Jowls to Bloodmage Lynnore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2605] = { id = 2605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Thirsty Goblin", description = "I've got an idea, see. I've heard of some strange creatures called dew collectors that live to the southwest... and that they are able to store water in special glands.\n\nI think that if I could get one of these glands, I could create a drink that would quench my terrible thirst! Do you think you could help me, {name}?\n\nLook for the cactus garden, {name}; that's where you'll find the dew collectors.", progress = "Please, tell me you found the dew collectors?", completion = "Oh, wonderful! Give it here -- let me drink it!", objectives = "Collect a Laden Dew Gland and bring it to Marin Noggenfogger in Gadgetzan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2606] = { id = 2606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Good Taste", description = "Blech! This stuff tastes terrible! So much for that idea...\n\nWait, what's that? Oh, I know, I know, you think I shouldn't give up on this stuff. Well, okay then.\n\nUhhhh, I have an idea! Brilliant! Take this dew to my friend Sprinkle -- she's an excellent chef. Tell her what we're up to here and that we want to make it go down a little easier.\n\nI mean, if it's going to taste that bad, it at least should have some kick to it... And I'm just not feeling it...", progress = "So old Marin's up to it again, eh? What's this concoction made from?", completion = "Marin's a good guy, don't get me wrong -- just a little... eccentric, I'd say.\n\nAnd of course he needs my help, yet again.", objectives = "Marin Noggenfogger wants you to speak with Sprinkle in Gadgetzan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2607] = { id = 2607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Touch of Zanzil", description = "It appears as if you've brought back more information than even I expected. This certainly is a strange turn of events, {name}.\n\nA cure? Hrm... Go down to the cellar and speak with Doc Mixilpixil - he may be able to help.", sourceObjective = "Speak with Doc Mixilpixil in the cellar of the Barracks.", sourceObjectiveStatus = "unverified-source-field" }
quests[2608] = { id = 2608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Touch of Zanzil", description = "Oh my, you look like death. Correction - I've seen death, you look worse than death. You, <sir/miss>, would be what death coughed up at his last physical.\n\nHah! You hear that Noarm? Write that one down!\n\n*Cough* Hrm yes, in order for me to help you, I'll need to draw some blood. Don't worry, it only hurts the first few... fifty times or so... /lay down when you're ready for the treatment, {name}.", objectives = "/Lay down to be examined by Doc Mixilpixil. How can he find the cure if he can't find the cause?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2609] = { id = 2609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Touch of Zanzil", description = "It's unanimous, {name}. You've got the 'itis.'\n\nLuckily, I have a cure for the 'itis.'\n\nHere's what I need: One bundle of simple wildflowers, one leaded vial, one bronze tube, and last but certainly not least, one spool of light chartreuse silk thread. Ol' Emma left a spool of it for me at 'The Finest Thread.' You can find the shop along the canals.\n\nHurry along now, {name}, and try not to touch anyone until you're cured. Oh, and Dr. Montgomery says you need a shower -- his words, not mine.", objectives = "Bring Doc Mixilpixil one bundle of Simple Wildflowers, one Leaded Vial, one Bronze Tube, and one Spool of Light Chartreuse Silk Thread. The 'itis' doesn't cure itself, young <fella/lady>.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2621] = { id = 2621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Disgraced One", description = "Regret. It is all I have now. One bad decision resulting in several horrible outcomes. If only I had waited for those orders. Maybe they would have detailed the horrors that awaited us in those cursed lands! Maybe they were to redirect us to another detail? Ultimately, it was my fault. All of it was my fault.\n\nSo here I stand, awaiting orders. I must know. I must have those orders.\n\nDispatch Commander Ruag resides in Stonard. Find him and find out what became of the orders.", completion = "Thrall's Grasp... The story is still fresh in my mind.\n\n<Commander Ruag shakes his head.>\n\nTerrible thing that happened to that regiment. The horde lost some of its best soldiers when that battalion was destroyed.", objectives = "Speak to Dispatch Commander Ruag at Stonard in Swamp of Sorrows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2622] = { id = 2622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Orders", description = "The orders? What could you possibly want with the orders?\n\nWhat are you implying, {name}? Of course I relayed those orders! The soldiers I sent the orders with were ambushed and brutally beaten by murlocs. Only one survived, if you can call that surviving. He can hardly speak, cannot walk, and must be fed through a tube. If you want to know what happened to those orders, speak with Bengor. I'm sure he is around here somewhere... and, {name}, be mindful of what you stick your nose into - it may get bitten off.", completion = "Swamp tal... talk.. talker...", objectives = "Speak to Bengor at Stonard in Swamp of Sorrows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2623] = { id = 2623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Swamp Talker", description = "Orders were given by the dispatch commander. We took... took orders. On way to Blasted Lands, ambushed.\n\nMurlocs... Many murlocs... One named Swamp Talker. Took orders from my hands as spear thrust into my skull. East... cave....\n\n<Bengor passes out.>", progress = "Awaiting orders.", completion = "It is worse than I imagined. Nineteen of my men could have been spared from the agony which they faced. If only I had not acted so irrationally.\n\nYou must help them, {name}! I am powerless to act.", objectives = "Retrieve the Warchief's Orders and return them to the Fallen Hero of the Horde.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2641] = { id = 2641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprinkle's Secret Ingredient", description = "When I was a kid, my sister used to do all the cooking. It was horrible! I could barely stomach some of her concoctions -- until I found what I like to call my \"secret\" ingredient! Add it to anything, and... WOW! It tastes great!\n\nWhat is it, you ask? It's a mushroom called the Violet Tragan. If you want me to help you turn this horrid-tasting brew into something edible, head to the Hinterlands, and look for a small lake there.\n\nOh, and remember, the Violet Tragan can only be found underwater.", progress = "Under the waters of that lake -- it's the only place where the Violet Tragan can be found.  Hope you're good at holding your breath!", completion = "That's the stuff, {name}!\n\nIt looks so good, I might just...  Haha, gotcha!", objectives = "Sprinkle in Gadgetzan wants you to collect a Violet Tragan and return it to her.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2661] = { id = 2661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delivery for Marin", description = "Here's the Violet Powder, {name}. Take it to Marin and tell him he owes me a favor!", progress = "Oh, {name}, you're finally back.  What have you brought?", completion = "Violet Powder, eh? Let's give it a try -- it sure couldn't make it any worse, that's for sure!", objectives = "Sprinkle wants to you take the Violet Powder to Marin Noggenfogger in Gadgetzan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2662] = { id = 2662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noggenfogger Elixir", description = "Now, to mix this powder in with the dew.\n\nCome back and talk to me in a minute... after I have perfected the fabulous Noggenfogger Elixir!", sourceObjective = "Marin Noggenfogger wants you to speak to him again after he creates his elixir.", completion = "Drink this! It's absolutely wonderful!!!\n\nI knew I had it in me... Oh thanks again, {name} for your help, but please, stand a little to the side, will you? You're blocking my business! I'm going to make millions on the fabulous Noggenfogger Elixir, millions!\n\nWhat's that? Sprinkle says I owe her a favor? Oh, that Sprinkle, such a kidder!", sourceObjectiveStatus = "unverified-source-field" }
quests[2681] = { id = 2681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stones That Bind Us", description = "It will take more than you alone to overcome the forces of Razelikh and his subordinates.\n\nGather a suitable group of adventurers and free my men of their eternal torture! Eighteen stones you must shatter.\n\nFight hard and die with honor, {name}.", completion = "You have done it, {name}! The poor, tortured souls can finally rest.\n\nOur work is not yet over, {name}. We have much to discuss and much more to accomplish.", objectives = "Free nine Servants of Razelikh, three Servants of Sevine, three Servants of Allistarj, and three Servants of Grol. Return to the Fallen Hero when your task is complete. You must remain within close proximity of the stones or the process will fail.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2701] = { id = 2701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroes of Old", description = "Please, take from this a relic of old. We no longer have a use for the item.\n\nMay it serve you well in your fight against the legion.", completion = "You are temporarily blinded by the sparkle and gleam.", objectives = "Open the chest and claim your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2702] = { id = 2702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroes of Old", description = "You have honored me with your nobility and heroism, {name}.\n\nYou have also honored them...", completion = "Indeed, you have honored us all. Our thanks alone are not sufficient.", objectives = "Speak to Corporal Thund Splithoof.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2721] = { id = 2721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kirith", description = "As one chapter of your adventure closes, another one begins, {name}.\n\nOne of my men is still unaccounted for, lost somewhere in the Blasted Lands. I am talking about Lieutenant Kirith, of course.\n\nAs I had mentioned earlier, we were both imprisoned and tortured by Allistarj, but poor Kirith, his strength of will faltered. I could hear the experiments from my cage; the tortured screams rang through the halls of the cave. That was the last I saw or heard of Kirith.", sourceObjective = "Find out what became of Lieutenant Kirith.", completion = "Trebor? Trebor sent you?", sourceObjectiveStatus = "unverified-source-field" }
quests[2741] = { id = 2741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Super Egg-O-Matic", progress = "The Super Egg-O-Matic is the latest of Curgle Cranklehop's inventions. It is quite an impressive piece of machinery.\n\nThe Super Egg-O-Matic sputters wildly as you approach the control panel.", completion = "You place the hippogryph egg into the machine. A series of beeps follows along with some strange mechanical sounds.\n\nIt appears that the Eggometer has weighed, measured, and packaged your egg. Now that's speedy service!" }
quests[2742] = { id = 2742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rin'ji is Trapped!", description = "Hey {race}!\n\nRin'ji lost axe and was captured! Please, help Rin'ji escape. Me know that {race} like you don't like Rin'ji's kind, but Rin'ji begs! Must get out of here!\n\nGot something for nice {race} if <he helps Rin'ji out of here/she helps Rin'ji out of here>...\n\nRin'ji is hiding something secret at the Overlook Cliffs.", completion = "This troll tablet must be the \"secret\" that Rin'ji was talking about.\n\nCovered with strange markings, you can not decipher what the tablet says.", objectives = "Escort Rin'ji out of the Quel'Danil Lodge, then find his hidden secret at the Overlook Cliffs to the east.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2743] = { id = 2743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cover of Darkness", description = "Let us not mince words, {race}; my time here is limited.\n\nYou must destroy the triad of power which protects the demon lord, Razelikh. Doing so will not be as simple a task as freeing a damned soul.\n\n<Kirith grins.>\n\nYou see, each of Razelikh's underlings wears a third of an amulet of Razelikh's creation around their neck. The very same amulet you will need in order to summon the arch demon.\n\nReturn to Trebor and tell him what is required to summon Razelikh. He will be able to instruct you further.", completion = "The demon lord displays a cunning almost as calculated as his brutality, {name}.", objectives = "Return to the Fallen Hero of the Horde with your findings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2744] = { id = 2744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Demon Hunter", description = "The triad is protected by Razelikh.\n\nIn exchange for their servitude, Razelikh granted each of them nearly unlimited power within the Blasted Lands. The amulet pieces are each attuned to the lifeforce of their owner, granting them immortality. As long as they remain within the Blasted Lands, they cannot be slain, their life spans extended until the end of days.\n\nThere is one who may be able to assist you further, {name}. Travel to Azshara and find the demon hunter, Loramus Thalipedes. Search the islands.", completion = "I will help you. Although, I do not think you fully understand what you are up against.", objectives = "Speak with Loramus Thalipedes in Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2745] = { id = 2745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infiltrating the Castle", description = "Hmm, an interesting tale, and not one to be taken lightly. Yeah, I can help you, but what you need to do is divvy out a form of justice that's not... legal, if you're to see this through to the end.\n\nLescovar and Marzon need to be dealt with, and swiftly. Do you think you're capable of such a thing?\n\nYou decide. If so, then make haste to the castle and find an old friend of mine, a gnome named Tyrion. He's been watching Lescovar now for a couple weeks. He should be able to help you end this.", completion = "What the...?! Don't sneak up on me like that! And keep your voice down! What in the name of the Shadow are you doing sneakin' up on me for? Can't you see I'm busy, you daft fool?\n\nWhat do you mean, what am I doing? I'm waiting for the next Dark Portal to open, what the heck do you think I'm doing? Speak your peace and be off with you... 'fore the guards notice the two of us hiding in the bushes together. I have a reputation to maintain.", objectives = "Speak to Tyrion in Stormwind Castle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2746] = { id = 2746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Items of Some Consequence", description = "Trias wants the timetable pushed up some, huh? Okay, we can do that, but I'm not ready. And know this, I'm doing the hard part, but you're the one that's going to get <his/her> hands dirty, understand? Good.\n\nOkay, I'll need you to get me a few things before I can put my plan into effect. I got the perfect disguise that'll get Spybot past those guards.\n\nBring me some silk and a couple apples. The silk's up to you, but Clara's little farm right outside the city has the perfect sized apples.", progress = "I've been watching Lescovar for a couple weeks now. Trias has never trusted him, but we didn't suspect he was involved in anything to do with the Defias Brotherhood. We were following leads that tied him to the Twilight's Hammer. Either way, he's become more dangerous than this city can deal with, and that's where we come in.\n\nGet me those items and we can put my plan into effect.", completion = "These will do nicely, {name}. Great job.\n\nI have the rest of the gear I'll need in my pack... thank the Light I just got a tailor friend of mine to make me a silk bag. I was running out of room carrying all my gear around.\n\nBefore Spybot heads in, let's get the details set so you know what you have to do.", objectives = "Bring 3 Silk Cloth and 2 of Clara's Fresh Apples to Tyrion in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2747] = { id = 2747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Extraordinary Egg" }
quests[2748] = { id = 2748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fine Egg", progress = "A fine egg is one that will, in ideal conditions, hatch free of the evil effects of the Gordunni ogres' incantations.", completion = "Very good, {name}. I will be sending this egg to Darnassus where I hope it will soon hatch!\n\nPlease accept this as a symbol of my gratitude." }
quests[2749] = { id = 2749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Ordinary Egg", progress = "Ordinary hippogryph eggs hatch about half the time. We do our best to nurture them and with a little luck, they will hatch.", completion = "So, you have found an ordinary egg, {name}? Please give it to me... And we can only hope for the best.\n\nI don't have much, but please accept this reward. If you ever find yourself in Feralas again, know that I am always here to take the eggs you find there." }
quests[2750] = { id = 2750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bad Egg" }
quests[2751] = { id = 2751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barbaric Battlements", description = "Twenty generations of Omosh have held this hammer, {name}. A hundred thousand tons of metal we have molded. Tragically, it all ends at Orokk, failure of the Omosh: Without kin and incapable of producing offspring.\n\nI cannot let the secret recipes of Omosh die with me! Someone must continue the legacy, Omosh or not!\n\nProve to Orokk you are capable, {name}. Bring for Orokk the following: Two patterned bronze bracers, two bronze greatswords, and two sharp claws. Bring them for Orokk and we shall continue.", progress = "Bronze, {name}! More bronze!!", completion = "The bloodline will fade but perhaps the legend of Omosh will continue!\n\nYou have proven that you are a blacksmith, {name}. For the blacksmith the reward is the satisfaction of seeing their weapons and armors coated in the blood of their enemies!\n\nMay the breastplates you create for the generations ahead be drenched in the blood of your enemies!", objectives = "Bring two Patterned Bronze Bracers, two Bronze Greatswords, and two Sharp Claws to Orokk Omosh in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2752] = { id = 2752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On Iron Pauldrons", description = "Orokk sees the eagerness in your eyes, {name}. Like a sponge you soak in the wisdom of the Omosh.\n\nThree lessons I shall teach!\n\nReturn to the anvil, soak in the heat of the forge, create for Orokk four bronze battleaxes and four bronze warhammers. Only then will you learn of the iron pauldron.", progress = "Show me your dedication, {race}.", completion = "You do Orokk proud, {name}. Read, learn of iron shoulders!", objectives = "Bring four Bronze Battleaxes and four Bronze Warhammers to Orokk Omosh in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2753] = { id = 2753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trampled Under Foot", description = "Only two more lessons Orokk will teach, {name}. Your muscles ache, I know, but continue on for the Omosh!\n\nBring to Orokk four green iron helms, four green iron bracers, and two green iron leggings - for this you learn and your enemies suffer!", progress = "Their skulls will crack under the pressure of your boots!", completion = "You remind Orokk of his grandfather, Chief Gorokk of Omosh! Read, learn of the iron boot.", objectives = "Bring four Green Iron Helms, four Green Iron Bracers, and two Green Iron Leggings to Orokk Omosh in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2754] = { id = 2754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Horns of Frenzy", description = "The final lesson Orokk teaches you, {name}. To the sacred anvil and forge you return! Bring for Orokk two solid iron mauls, two silvered bronze boots, and two silvered bronze gauntlets.\n\nSee the fear in their eyes as you approach!", progress = "Show the iron who is in charge, {name}!", completion = "Astounding! You have learned the way of the Omosh, {name}!", objectives = "Bring two Solid Iron Mauls, two Silvered Bronze Boots, and two Silvered Bronze Gauntlets to Orokk Omosh in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2755] = { id = 2755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Joys of Omosh", description = "Orokk is not crying, {name}. Soot is in eye.\n\n<Orokk wipes a tear away.>\n\nThere is one last Omosh family secret Orokk will teach you. Orokk will die happy, thanks to {name}.\n\nLearn Omosh dance of joy and then you learn fist of iron!", completion = "<Orokk pants.>\n\nIt has been a very long time since Orokk has done the Omosh dance of joy. Learn now, {name}!", objectives = "Watch and learn the Omosh Dance of Joy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2756] = { id = 2756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Old Ways", description = "In the time of legends, Aturk would crush the skulls of his enemies and grind the bone into a fine powder for use in filament. Long gone are those days, {race}. The Warchief calls for peace among the clans. Old enemies are now only watched with weary eyes!\n\nUnbelievable, I know, but such is the will of Thrall.\n\nEnough lamenting! You are here to learn, and learn you will! Bring me four steel breastplates and four steel helms and you will gain a taste of war!", progress = "Aturk, like time, waits for no one! Hurry up fool!", completion = "It seems you are but another complacent lemming of the Warchief, {name}. How disappointing.\n\nHow I long for a glorious death upon the battlefield. Instead, I am stuck here, by order of Thrall, to teach infants how to craft! Watch and learn, child!", objectives = "Bring four Steel Breastplates and four Steel Plate Helms to Aturk the Anvil in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2757] = { id = 2757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Booty Bay or Bust!", description = "Listen, kid, you're not gonna learn anything hanging around here.\n\nI know a guy who knows a guy. He hangs around the smithy in Booty Bay. If you show him this insignia, he'll tell you all about mithril.\n\nSo whadd'ya say? Leave this kid stuff to the babies in diapers, {name} -- it's time to move on.\n\nIf you're interested, his name's McGavan. Show him this trinket and he'll recognize your commitment.", objectives = "Speak with McGavan in Booty Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2758] = { id = 2758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Origins of Smithing", description = "When I was about your age, a dwarf by the name of Galvan took me under his wing and trained me in the ways of the armorsmith. Before he left for Booty Bay, he made me promise to train all those with the desire and determination to advance in the craft of blacksmithing -- so here I am -- all these years later.\n\nSo, now it's time for you to learn a little something. Make me six golden scale bracers and you will learn where smithing comes from, {name}.", objectives = "Bring six Golden Scale Bracers to Hank the Hammer in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2759] = { id = 2759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search of Galvan", description = "Although Galvan left Booty Bay many years ago, members of the order still remain in town, hoping to one day find another worthy of Galvan's tutelage.\n\nTake this insignia and present it to McGavan in Booty Bay.\n\nIf you actually make it that far, he'll know that you are worthy. I have faith, {name}!", objectives = "Speak with McGavan in Booty Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2760] = { id = 2760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mithril Order", description = "Most of our recruits never make it to Booty Bay, {name}. The shine of the insignia is enough to trigger the loot lust in even the staunchest of blacksmiths. Fools they be, as the insignia is a drop in the bucket compared to the wealth of items you'll see!\n\nFind Galvan the Ancient and show him this pin. His residence is far to the north, between Zul Gurub and the Mosh'Ogg ogre mound.", progress = "Hail! Come closer; show Galvan what you have.", completion = "Ah, many years it has been since one has been worthy of the Mithril Order's initiation. We will start now!", objectives = "Speak with Galvan the Ancient in Stranglethorn Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2761] = { id = 2761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smelt On, Smelt Off", description = "Many blacksmiths believe that mining and smithing are separate, independent jobs; but can there be blacksmithing without mining? Ah ha -- it is an impossibility! The accomplished blacksmith must also be an accomplished miner.\n\nShow Galvan that you are capable, {name}. Bring me forty bars of iron and forty bars of mithril. For this, Galvan will teach you the ways of the ornate mithril pants!", objectives = "Bring forty Mithril Bars and forty Iron Bars to Galvan the Ancient in Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2762] = { id = 2762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Silver Deceiver", description = "It is said that truesilver is stronger and more durable than mithril. Galvan does not disagree with this assessment of the minerals, but contrary to its name, truesilver is not true! Mithril is a far nobler mineral! HAH! Regardless, for this lesson you will need to find the great silver deceiver, {name}.\n\nBring me forty bars of mithril and five bars of truesilver. In exchange, you will be taught the secret of ornate mithril gloves and more importantly, learn that truesilver is a liar!", progress = "After such mining, your muscles bulge and your body aches!", completion = "She's a cruel mistress, is she not, {name}? I'm speaking of truesilver, naturally. Aye, Galvan spent over a decade in the mountains of Alterac learning this lesson. Take this and learn from it all that you can!", objectives = "Bring forty Mithril Bars and five Truesilver Bars to Galvan the Ancient in Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2763] = { id = 2763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Art of the Imbue", description = "The harvesting of precious gems is of utmost importance to our craft, {name}. Few gems are more precious than the citrine. The magical properties we imbue into our goods are amplified greatly by the presence of citrine.\n\nFor this lesson, we will fortify forty bars of mithril with four citrines. The result will be a better understanding of magical gemology and the knowledge to create ornate mithril shoulders.", objectives = "Bring forty Mithril Bars and four Citrines to Galvan the Ancient in Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2764] = { id = 2764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Galvan's Finest Pupil", description = "If you are ready to conclude your training with Galvan, you should journey to Gadgetzan.\n\nThere, you will find my finest pupil: Trenton Lighthammer. He has much to teach you in the ways of ornate mithril. Otherwise, remain here and learn!\n\nOh, Gadgetzan is in Tanaris, of course!", sourceObjective = "Speak with Trenton Lighthammer in Gadgetzan.", completion = "Galvan the Ancient sent you??\n\n<Trenton bows.>\n\nIt is a great honor to meet another of the master's pupils!", sourceObjectiveStatus = "unverified-source-field" }
quests[2765] = { id = 2765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expert Blacksmith!", description = "When you first came to me, I knew that you would turn out to be one of my finest pupils! It was without hesitancy that you gave up a trinket of some power to McGavan. You did this only so that you could meet me. Such blind faith and devotion to the craft should be rewarded.\n\nYou have attained expertise over blacksmithing, {name}. Reap the rewards!", objectives = "Claim your reward from Galvan the Ancient!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2766] = { id = 2766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find OOX-22/FE!", description = "You have uncovered some sort of strange, egg-shaped device made from metal.  Fiddling with one of its knobs springs the egg to life, as it opens up into some sort of gnomish robotic contraption!  A voice from inside the robotic egg crackles to life.\n\n\"My name's Oglethorpe Obnoticus, and my homing robot has crashed!  I will reward you for its recovery; please take this beacon to the robot!\"\n\n\"I now have computed the coordinates of the robot for you; it is in a cave near Feral Scar Vale!\"", progress = "You appear to have uncovered the wreckage of... a robotic chicken?  The voice from within the egg crackles to life again:\n\n\"Yes, excellent work!  This is indeed my homing robot, though my sensors indicate that it needs a jump start before it can fly back to Booty Bay for repairs.  Go ahead and place the beacon inside the rover - the beacon will take care of the rest!\"", completion = "You place the egg... distress beacon... inside the chicken... homing robot.\n\nHums and whirs are heard from inside the robot as it struggles to stand up.  After the robot comes to life, Oglethorpe's voice is heard once more, but now from inside the robot:\n\n\"OOX-22/FE is working at least, but it needs major repairs!  It is much too heavy for you to carry it... but I think I have an idea.  Are you up for watching over it some more?\"", objectives = "Take the distress beacon to Oglethorpe's homing robot in a cave near Feral Scar Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2767] = { id = 2767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescue OOX-22/FE!", description = "The gnome's voice crackles once again from the robot:\n\n\"I need to move OOX-22/FE to an open, safe place so it can begin a lengthy take-off procedure.  It has built-in cloaking, but I need time on my end to make it operational again.  Escort the robot from its current location to, let's say, the main road!  That should be a perfect place, and long enough, to get things online!\"\n\n\"Escort it safely and then come talk to me in Booty Bay!  Oglethorpe Obnoticus - out!\"", completion = "Oh, YOU'RE the great savior of OOX-22/FE!  I cannot even begin to express my thanks for your assistance!  My homing robot series needs more development, but your recovery has saved me countless hours of extra rebuilding time, as well as many gold pieces in manufacture costs!\n\nPlease, take your choice of any of these items I have.  Thank you again for your generous assistance {name}, my robots and I are in your debt!", objectives = "Escort OOX-22/FE to safety, then report to Oglethorpe Obnoticus in Booty Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2768] = { id = 2768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Divino-matic Rod", description = "Sergeant Bly stole from me!  He said he'd only borrow it, but he stole my cherished divino-matic rod!!  Without that rod how will I know where to dig new water holes??\n\nFind Bly and bring me my rod!  I heard he led his band of ill-reputed adventurers to go treasure hunting in Zul'Farrak to the west.  I bet you'll find him there.\n\nLet's hope the trolls took care of him, because if you have to fight him for the rod then you're in for a serious fight.", progress = "Did you find Sergeant Bly?  Did you get my divino-matic rod?", completion = "You found it!  Well done, {name}!  Did you have to fight Bly for it?  I hope you knocked him and his band down good and hard!", objectives = "Bring the Divino-matic Rod to Chief Engineer Bilgewhizzle in Gadgetzan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2769] = { id = 2769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brassbolts Brothers", description = "Have you met the Brassbolts brothers?  They're over in the Shimmering Flats, in Kalimdor, racing their rocket car against the goblins.  They usually win which is no surprise--the goblin car blows up so much it barely ever crosses the finish line!\n\nBut even then, the Brassbolts brothers are always looking for new ways to make their car go faster, and Wizzle told me he needs a very rare component for his next experiment.\n\nHe probably needs help getting that part.  Speak to him and find out.", completion = "Ah, you want to help me?  Great!\n\nThere's a part I want for an experiment I'm working on, and I need a brave {class} like you to help me get it!", objectives = "Speak with Wizzle Brassbolts in the Shimmering Flats.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2770] = { id = 2770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gahz'rilla", description = "Deep in Zul'Farrak, the sand troll city in Tanaris, there is a sacred pool.  From that pool the trolls summon a huge beast!  Gahz'rilla!  He's so fierce that even his scales crackle with energy.  It's that energy I want to harness for my car!\n\nBring me the electrified scale of Gahz'rilla!\n\nBut the summoning of Gahz'rilla is a well-kept secret of the trolls.  To face him, you must first wrest the secret from them.", progress = "Do you have the scale?  I can't wait to try different ways to harness its energy!", completion = "Wow, you got the scale!  Thanks, {name}.  I can't wait to get to work on this thing!\n\nSo you saw Gahz'rilla?  Was he as big as they say??", objectives = "Bring Gahz'rilla's Electrified Scale to Wizzle Brassbolts in the Shimmering Flats.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2771] = { id = 2771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Good Head On Your Shoulders", description = "It seems as if master had this planned from the start. I was not taught to create the items which you learned to create and you were not taught the items which I learned to create.\n\nThe master is wise, {name}. We shall teach each other!\n\nShow me how to make a mithril coif and ornate mithril shoulders and I shall show you how to create an ornate mithril helm.", objectives = "Bring two Mithril Coifs and one Ornate Mithril Shoulder to Trenton Lighthammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2772] = { id = 2772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The World At Your Feet", description = "At last year's All-Valley Blacksmithing Championship, all those who watched saw my leg get swept from under me by a cowardly dog from the Venture Co. Foundry. What they didn't know, however, was the reason I was able to continue and ultimately win the tournament: That's right, ornate mithril boots!\n\nI will need to learn how to craft ornate mithril pants for this year's tournament, however, as a Venture Co. shredder is an entrant! Teach me the way of the pants and learn the way of the boot!", objectives = "Bring two Heavy Mithril Boots and one Ornate Mithril Pants to Trenton Lighthammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2773] = { id = 2773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mithril Kid", description = "Around these parts I am known as the Mithril Kid. I supply ornate mithril to adventurers from around the world.\n\n<Trenton whispers.>\n\nLittle do they know that I do not know the technique to fashion ornate mithril gloves. Shhhh! This will be our little secret.\n\nTeach me the technique to create ornate mithril gloves, {name}, and in exchange, I will show you the resultant of the culmination of my training under Galvan: the ornate mithril breastplate.", objectives = "Bring two Heavy Mithril Breastplates and one Ornate Mithril Gloves to Trenton Lighthammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2781] = { id = 2781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Caliph Scorpidsting", description = "WANTED: Caliph Scorpidsting!\n\nThe Gadgetzan Water Company of Gadgetzan, Tanaris will pay a high bounty for the head of Caliph Scorpidsting, leader of the Wastewander outlaws.  His crimes include:\n\n1.  Murdering Gadgetzan Water Co. employees!\n2.Stealing Gadgetzan Water Co. resources!\n3.Seizing Gadgetzan Water Co. property!\n\nBring proof of Caliph Scorpidsting's demise to Chief Engineer Bilgewhizzle for an immediate reward!", progress = "Yes {class}, I am an official of the Gadgetzan Water Company.  What can I assist you with?", completion = "Finally - justice is served!  You have struck a mighty blow against those vile nomads!  With Scorpidsting's demise, this might be just the thing to finally push those squatters off of Gadgetzan's water wells!\n\nBy the authority of the Gadgetzan Water Company, I gladly award you with this bounty.  You've done a great service for us all.", objectives = "Bring the head of Caliph Scorpidsting to Chief Engineer Bilgewhizzle in Gadgetzan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2782] = { id = 2782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rin'ji's Secret", description = "The tablet is covered with Witherbark troll markings. Rin'ji's secret truly is a mystery... \n\nIt's possible that you might have something quite valuable on your hands here. On the other hand, quite the opposite is also possible. A Witherbark troll in distress would probably do anything to find his way out of trouble...", progress = "Well, now, what is this?", completion = "This tablet... Quite unusual... Where did you find this, {name}?", objectives = "Oran Snakewrithe, a well known scholar on matters concerning the Witherbark trolls, may be able to decipher the tablet. She is known to reside within the Magic Quarter of the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2783] = { id = 2783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Petty Squabbles", description = "We fight the wrong enemy, {name}.\n\nThe true power in these lands continues to grow in strength and number while we squabble over scorched earth with orcs.\n\nDo we continue to fight a war in these lands against the Horde, only to be routed one day by the armies of the Burning Legion? It is futile.\n\nPut your differences aside, {name}, speak with the fallen hero of the Horde. He knows the truth behind the Blasted Lands.", sourceObjective = "Speak with the Fallen Hero of the Horde at the border of the Blasted Lands and the swamp.", completion = "The Alliance wishes to assist?\n\nI thought to never see this day again. A day in which the Alliance fights side by side with the Horde against a common enemy.\n\nIt shall be... we will unite.", sourceObjectiveStatus = "unverified-source-field" }
quests[2784] = { id = 2784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fall From Grace", description = "Hear my story, {race}.", completion = "As a spirit, I am powerless, {name}. Assist me. Allow me to regain my honor.", objectives = "Listen to the Fallen Hero of the Horde tell his story.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2801] = { id = 2801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tale of Sorrow", description = "Before we may continue, you must hear my story.", completion = "The time to act is now, {name}.", objectives = "Listen to the Fallen Hero of the Horde tell his story.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2821] = { id = 2821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mark of Quality", description = "My philosophy on leatherworking is that the work must be the best quality possible - no compromises.  Anyone who says that quality doesn't matter is trying to sell you ocean-front property in Dun Morogh!\n\nIn my latest pursuit of high-quality materials, I have run across thick yeti hides.  The Yeti are native to Feralas, with many found in Feral Scar Vale.  I want some, and I'll give you a choice of one of my leather goods for a stack of ten.  If that sounds fair to you, then we're in business.", progress = "A stack of ten thick yeti hides will net you a choice of one of my crafted items.  Because I care about quality, I am able to ensure you'll get a good item!\n\nIf you can't seem to find yetis, I know where some might be.  Try looking just inland of the Forgotten Coast, around Feral Scar Vale.", completion = "Did you stop and examine the texture of these hides?  Properly treated, these hides could very well be stronger than iron.  Not many people know about these hides, and that in combination with the vast treating solutions I know will allow me to potentially make items with a true mark of quality... thanks to you, of course!\n\nAnd now, please choose from what I am able to offer you for your service!", objectives = "Bring 10 Thick Yeti Hides to Pratt McGrubben in Feathermoon Stronghold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2822] = { id = 2822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mark of Quality", description = "I take pride in my leather work, and I feel it shows; quality should never be compromised.  Anyone who says that quality doesn't matter would also have you believe that the earth does not keep secrets!\n\nIn my latest pursuit of high-quality materials, I have discovered thick yeti hides.  Yetis are native to Feralas, often found west of here in Feral Scar Vale.  I'll give you a choice of one of my leather goods for a stack of ten.  If that is agreeable to you, then we are set!", progress = "Were you able to get a stack of ten thick yeti hides?  My leather goods are second to none, and I'll share a sampling with you should you have the hides.\n\nIf you can't seem to find yetis, I know where some might be.  Try looking west of here, just inland of the Forgotten Coast around the Feral Scar Vale.", completion = "Ah, excellent!  These hides, when given a special treatment, are as resilient as iron I tell you!  It will take many tries in order to get the right mix down for the tanning, but I am confident they will bring my mark of quality to the next level.\n\nAs for you, {name}... your assistance has proven invaluable to me.  Please take your choice from these items I have crafted.", objectives = "Bring 10 Thick Yeti Hides to Jangdor Swiftstrider in Camp Mojache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2841] = { id = 2841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rig Wars", description = "Gnome technology - two years ago its most common use was as a punch line. Times certainly have changed. Now they've got a new rig built that's better than all our shredder models combined. I need the blueprints, {name}!\n\nUnfortunately, the plans are locked away in a safe near Mekgineer Thermaplugg. To make matters worse, the combination to the safe is only known by Mekgineer Thermaplugg.\n\nDo whatever you have to do to get that combination, {name}. Then crack open that safe and bring back those blueprints!", progress = "I don't see any blueprints. Did you hide them somewhere on your body or are you just standing around here to irritate me?", completion = "I knew you could do it, {name}! Sovik on the other hand, he had his doubts.\n\n\n\nNow that we have the blueprints in our possession, it is only a matter of time before we figure out all of the gnomish innovations that went into the creation of the rig and make them goblin innovations for our new shredder models.", objectives = "Retrieve the Rig Blueprints and Thermaplugg's Safe Combination from Gnomeregan and bring them to Nogg in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2842] = { id = 2842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chief Engineer Scooty", description = "As soon as we got word from Kernobee about the new gnomish rig, Scooty and I began work on the Transpolyporter 6000: The fastest and most reliable way to Gnomeregan.\n\nIt's finally ready for passengers to board, {name}. If you want to give it a try, go to Booty Bay and talk with Scooty at the wind rider roost. To get to Booty Bay, take the boat from Ratchet.\n\nOf course, you could always try and make the run to Gnomeregan through the dwarf infested mountains of Dun Morogh!", sourceObjective = "Speak with Scooty in Booty Bay.", completion = "She's a beauty, isn't she? Pinnacle of goblin transport technology -- only exploded a dozen or so times.\n\nDon't worry, {name}, I've got her all fixed up. She won't blow up on you - and if she does, it'll be quick and painless.", sourceObjectiveStatus = "unverified-source-field" }
quests[2843] = { id = 2843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnomer-gooooone!", description = "As long as you have the transponder in your possession, all you need to do is step on the pad and you'll be teleported to Gnomeregan.\n\nYou may experience some unusual side effects, but none of those should be permanent... anymore.\n\nI almost forgot the most important part - getting back. When you're ready to come back, just step on the transpolyporter pad in Gnomeregan!\n\nNow to calibrate the transponder to your size and weight.", completion = "All done! When you're ready, just step on the pad.", objectives = "Wait for Scooty to calibrate the Goblin Transponder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2844] = { id = 2844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Giant Guardian", description = "I am no good, {name}. I was 'spose to be watchin' over my little friend, Shay, and somehow, she got away from me. I'm not all that sure what happened, really, but last time I saw her, we was walkin' through the ruins just north of here.\n\nEverythin' was goin' fine, but then I turned around, and... she was gone.\n\nNow I jus can't quite figure out what I should do here. Got any ideas, {name}? I'm awful worried.\n\nHey, how 'bout you go look fer Shay? Yer legs can travel much faster 'n mine.", sourceObjective = "Locate the lost night elf girl.", completion = "Oh, I am so glad you found me! I must admit, I am a bit lost... But isn't this a beautiful place?", sourceObjectiveStatus = "unverified-source-field" }
quests[2845] = { id = 2845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wandering Shay", description = "Do you think you could help me find my way back to my friend, Rockbiter? He was supposed to be watching me... But I do have a tendency to wander off now and then. There are just so many things to see, and I get so distracted.\n\nThere is one thing that will always work to get my attention, though.\n\nInside this chest, you'll find a bell that is very precious to me. I just love the sound of it. You have my word, if I wander off, all you have to do is ring it and I'll come running back.", progress = "I was gettin' worried 'bout ya! Thank you so much for bringin' Shay home, {name}.", completion = "What? You say dis bell will work when Shay runs off? Well, how 'bout that!\n\nSince you did so much fer me, here ya go, {name}.", objectives = "Pick up Shay's Bell from the chest.\n\nEscort Shay Leafrunner to Rockbiter's camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2846] = { id = 2846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiara of the Deep", description = "Long ago I possessed a beautiful piece of jewelry, the Tiara of the Deep.  And not only was it pretty--it held great power for those with the knowledge to use it.\n\nSo when word of the tiara reached the Hydromancer Velratha, she had to have it.  She sent agents to my home and they stole it while I was away.  The thieves!\n\nI want my tiara back!  Go to Zul'Farrak, the troll city in Tanaris, find Velratha and wrench the tiara from her.  Return it to me and you'll earn my favor.", progress = "Do you have the tiara, {name}?  Has Velratha learned the price of crossing me?", completion = "Wonderful!  You found it!  And what's just as important--Velratha no longer has it!  Thank you, {name}.  I am forever in your debt!\n\nAnd if I sounded a little... mean before, pay it no mind.  You'll find me a much nicer person to those who haven't stolen from me.", objectives = "Bring the Tiara of the Deep to Tabetha in Dustwallow Marsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2847] = { id = 2847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Leather Armor", description = "{name}, you're becoming quite skilled as a leatherworker!  I know some patterns you might be interested in... Wild Leather armor!  Wild Leather taps into the potent and chaotic properties of wildvines, found in areas of lush vegetation and on some of the creatures there.  The armor made using it is second to none for people of your skill, guaranteed.\n\nI'll teach this to you, but you'll be working for me for a while.  The first cost is simply ten pieces of thick leather.  After this, we'll talk specifics.", objectives = "Bring 10 Thick Leather to Pratt McGrubben in Feathermoon Stronghold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2848] = { id = 2848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Leather Shoulders", description = "Wild Leather shoulders support the wearer's frame extremely well, offering top notch protection of the upper arms and the shoulders themselves.  As with all Wild Leather armor, a potent but random benefit is applied to the item as the wildvine is stitched in.\n\nFor this pattern, I will require six thick armor kits and a wildvine.  That shouldn't be too tall of an order for you to fill.", objectives = "Bring 6 Thick Armor Kits and a Wildvine to Pratt McGrubben in Feathermoon Stronghold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2849] = { id = 2849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Leather Vest", description = "Wild Leather vests are the staple of any Wild Leather armor set.  The frame of the vest blends with the wildvine to produce a product that offers maximum protection of the torso while allowing for the potent magic to work its way through the garment.\n\nFor this pattern, I will require two Turtle Scale breastplates, two sets of Turtle Scale gloves, and a wildvine.  It's a tall order, but one you should have little difficulty in filling for me.", objectives = "Bring 2 Turtle Scale Breastplates, 2 Turtle Scale Gloves, and a Wildvine to Pratt McGrubben in Feathermoon Stronghold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2850] = { id = 2850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Leather Helmet", description = "A Wild Leather helmet offers the wearer superior protection to the vital areas of the head without a sacrifice in comfort.  As with all Wild Leather armor, the integrated wildvine yields a powerful but random enhancement to the frame of the helm.  Leather wearers will definitely want this piece!\n\nFor this pattern, I will need two Nightscape tunics, two Nightscape headbands, and a wildvine.  Complete this order and the pattern will be yours!", objectives = "Bring 2 Nightscape Tunics, 2 Nightscape Headbands, and a Wildvine to Pratt McGrubben in Feathermoon Stronghold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2851] = { id = 2851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Leather Boots", description = "You've learned quite a bit now, {name}; still, there is more for you to learn.  Next are Wild Leather boots, the cornerstone of any set.\n\nThese boots are crafted to cradle the foot in comfort while bracing it against the hazards of adventuring.  The soft soles are a blessing to those seeking quiet movement in footwear.\n\nFor this pattern, I need an order of two Nightscape pants and two Nightscape boots filled.  I also will require two wildvines... not just one.  When you have all this, let me know.", objectives = "Bring 2 Nightscape Pants, 2 Nightscape Boots, and 2 Wildvines to Pratt McGrubben in Feathermoon Stronghold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2852] = { id = 2852, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Leather Leggings", description = "With the basics down, you are ready to master more complex fare, {name}.  Wild Leather leggings are some of the sturdiest and powerful leather gear around.  The waist, thighs, calves, and the vitals - all are given tremendous protection.  Coupled with the enhancement that the wildvine provides, adventurers who own it will thank you each time they see you.\n\nFor this pattern, I need an order of two Turtle Scale helms, two Turtle Scale bracers, and two wildvines filled.", objectives = "Bring 2 Turtle Scale Helms, 2 Turtle Scale Bracers, and 2 Wildvines to Pratt McGrubben in Feathermoon Stronghold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2853] = { id = 2853, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Master of the Wild Leather", description = "Well {name}, you are the definition of diligence.  There is one pattern left for Wild Leather armor; you've mastered the others.  I won't require you to toil needlessly for the pattern.  You've earned it outright, and then some... but I cannot give it to you myself.  My teacher, the one who brought me into the craft, is the one who must reward you.\n\nTake this letter to Telonis; he teaches leatherworking in Darnassus.  Show him the letter, and let him acknowledge you as an equal, as I do.", objectives = "Give Pratt's Letter to Telonis, the master leatherworker of Darnassus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2854] = { id = 2854, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Leather Armor", description = "{name}, your skill as a leatherworker precedes you.  I possess leatherworking lore you would be wise to acquire... Wild Leather armor!  Wild Leather taps into the potent and chaotic properties of wildvines, found in areas of lush vegetation and on some of the creatures there.  Armor made using it is second to none for a crafter of your skill, guaranteed.\n\nI'll teach you, but you'll be working for me for a while.  The first cost is simply ten pieces of thick leather.  After this, we'll talk specifics.", progress = "We must be clear; you shall be apprenticed to me while you learn the art of Wild Leather armor.  Because wildvines are both potent and chaotic, it yields a random but strong benefit to the already strong armor you will be making.  This knowledge, however, was not easy for me to acquire.\n\nThe initial cost to begin this process is ten pieces of thick leather.\n\nOnce that is done, we'll get to the work you need to do in order to obtain the patterns.", completion = "Well {name}, I'm glad to have you on board as my apprentice.  You've made a wise decision as a leatherworker; those who make use of leather armor will be clamoring to you once you learn how to master the art of Wild Leather.\n\nLet's get to work - where do you want to start?", objectives = "Bring 10 Thick Leather to Jangdor Swiftstrider in Camp Mojache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2855] = { id = 2855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Leather Shoulders", description = "Wild Leather shoulders support a wearer's frame extremely well, offering superior protection of the upper arms as well as the shoulders.  As with all Wild Leather armor, a random yet very potent enhancement is imbued within the item as the wildvine is stitched in.\n\nFor this pattern, I will require six thick armor kits and a wildvine.  That shouldn't be too tall of an order for you to fill.", objectives = "Bring 6 Thick Armor Kits and a Wildvine to Jangdor Swiftstrider in Camp Mojache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2856] = { id = 2856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Leather Vest", description = "Wild Leather vests are the staple of any Wild Leather armor set.  The frame of the vest and the wildvine weave within it produces a product that offers maximum protection of the torso while allowing for potent magic to work its way through the garment.\n\nFor this pattern, I will require two Turtle Scale breastplates, two sets of Turtle Scale gloves, and a wildvine.  This is not an easy lesson, but it is one you certainly have the skill to complete.", objectives = "Bring 2 Turtle Scale Breastplates, 2 Turtle Scale Gloves, and a Wildvine to Jangdor Swiftstrider in Camp Mojache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2857] = { id = 2857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Leather Helmet", description = "A Wild Leather helmet offers the wearer superior protection to the vital areas of the head without a sacrifice in comfort.  As with all Wild Leather armor, the integrated wildvine yields a powerful but random magic imbuement to the helm's frame.  Leather wearers will definitely want this piece!\n\nFor this pattern, I will need two Nightscape tunics, 2 Nightscape headbands, and a wildvine.  Complete this lesson and the pattern will be yours!", objectives = "Bring 2 Nightscape Tunics, 2 Nightscape Headbands, and a Wildvine to Jangdor Swiftstrider in Camp Mojache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2858] = { id = 2858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Leather Boots", description = "Your knowledge of Wild Leather armor grows, {name}; still, there is more for you to learn.\n\nWild Leather boots are the cornerstone of any set.  Such boots are crafted to cradle the foot in comfort while bracing it against the hazards of adventuring.  The soft soles are a blessing to those seeking quiet movement in footwear.\n\nFor this pattern, I need two Nightscape pants and two Nightscape boots crafted.  I also will require two wildvines... not just one.  When you have these items, we will proceed.", objectives = "Bring 2 Nightscape Pants, 2 Nightscape Boots, and 2 Wildvines to Jangdor Swiftstrider in Camp Mojache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2859] = { id = 2859, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Leather Leggings", description = "You are ready to master more complex lessons, {name}.  Wild Leather leggings are some of the sturdiest and powerful leather gear around.  The waist, thighs, calves, and the vitals - all are given tremendous protection.  Coupled with the enhancement that the wildvine provides, adventurers who own it will thank you each time they see you.\n\nFor you to gain this pattern, I need two Turtle Scale helms, two Turtle Scale bracers, and two wildvines.", objectives = "Bring 2 Turtle Scale Helms, 2 Turtle Scale Bracers, and 2 Wildvines to Jangdor Swiftstrider in Camp Mojache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2860] = { id = 2860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Master of the Wild Leather", description = "{name}, you have learned all I am able to teach you.  There is, however, one remaining pattern for Wild Leather armor.  I will not require you to toil needlessly for this; you've earned it outright, and then some.  This pattern, however, is one that I cannot freely share with you.\n\nMy teacher, the one who brought me into the craft, is the one who must reward you.  Take this note to Una; she teaches leatherworking in Thunder Bluff.  Show her the letter, and let her acknowledge you as an equal, as I do.", objectives = "Give Jangdor's Letter to Una, the master leatherworker of Thunder Bluff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2861] = { id = 2861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tabetha's Task", description = "Rumor is that Tabetha, a mage colleague who lives deep in Dustwallow Marsh, has a bone to pick with a certain sand troll in Zul'Farrak.  If you speak with Tabetha she can tell you more.\n\nAnd bring some friends with you, {name}.  If Tabetha has you go to Zul'Farrak then you're not going to want to go alone.\n\nYou will find Tabetha's cottage west of Theramore, and just north of the Stonemaul Ruin.", completion = "That's right.  I do have a bone to pick with a troll.  A few bones.  All her bones!\n\nWant to help me?", objectives = "Speak with Tabetha in Dustwallow Marsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2862] = { id = 2862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War on the Woodpaw", description = "The gnolls... they are more than a nuisance.  They are a constant threat to the existence of this very camp!  It is irrelevant whether they are indigenous to Feralas or not; if we do not strengthen our resolve against them, we will find ourselves driven out of the entire region.\n\nThe gnoll attacks against the camp have become more fevered as of late.  We need your aid in thinning their numbers; bring to me ten of their manes, and I will reward you handsomely for your effort.\n\nGo!", progress = "We drive them back, and yet they still attack!  Someone or something must be driving them into a frenzy... oh, you have returned, eh {name}?  Do you have the manes I require for the bounty to be met?", completion = "This is proof of a good start, {name}.  Your skills as a soldier are to be commended.\n\nYou are not the only one I ask that task of.  Many before you have fought them, and in times past, our efforts have kept them at bay.  Recently though, their attempts to push northward into our area of influence have increased dramatically.  Their attacks have also become more savage... almost as if they were desperate.\n\nI have a plan though, {name}, that might settle things once and for all against them...", objectives = "Bring 10 Woodpaw Gnoll Manes to Hadoken Swiftstrider in Camp Mojache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2863] = { id = 2863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alpha Strike", description = "The plan is for various leaders of the gnolls - Alphas as they call themselves - to be taken down within rapid succession.  If we're able to execute this sort of swift and precise devastation against them, it would cause chaos in their ranks.  Perhaps it would also drive a message through their thick flea-bitten heads that we can and will destroy them!\n\nI want you to be the messenger of my will; eliminate five of their Alphas within one hour for this to work {name}, or we'll remain at this impasse!", completion = "You've done as I have asked, and for that I salute you.  Take this small reward as compensation for your efforts, {name}.\n\nWith their numbers thinned and their leaders slain, the gnolls will think twice about storming the camp.  This doesn't conclude the issue at hand, however...\n\nThere must be some reason why the gnolls have been whipped into such a frenzied state.  Before they have a chance to regroup though, I want to find out what is causing it.", objectives = "Kill 5 Woodpaw Alphas and return to Hadoken Swiftstrider within one hour.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2864] = { id = 2864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tran'rek", description = "My cousin Tran'rek is in a tight spot.  He promised me a load of scarab shells weeks ago and he hasn't delivered.  He's my cousin, so I'd hate to have to send someone to Gadgetzan to break something on him.\n\nCan you speak to Tran'rek for me?  Let him know he needs to get that delivery together before I do something rash?\n\nGadgetzan is in northern Tanaris, in Kalimdor.", completion = "Hello!\n\nOh, you spoke to my cousin Krazek?  How is he?  I hope Booty Bay is treating him well...\n\nScarab shells, you say?  Well... let me tell you a story...", objectives = "Speak with Tran'rek in Gadgetzan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2865] = { id = 2865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scarab Shells", description = "The scarabs of Tanaris have very hard shells!  Hard enough to use as a building material for lots of things.  So many things!\n\nIn fact, those shells are so useful... the scarabs were hunted all to near extinction!\n\nI know where there are more scarabs, and if you promise to bring me their shells then I'll tell you where they are.  Promise?\n\nOk, the scarabs have a colony in Zul'Farrak.  I guess the trolls don't hunt them for their shells.\n\nBut you can!  Go to Zul'Farrak and get me uncracked shells!", progress = "Do you have the shells?  My cousin in Booty Bay is waiting for a load of them, and he's getting impatient!", completion = "Oh, great!  You got them!\n\nThanks, {name}.  You're a real lifesaver!", objectives = "Bring 5 Uncracked Scarab Shells to Tran'rek in Gadgetzan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2866] = { id = 2866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ruins of Solarsal", description = "To our south are the Ruins of Solarsal; this is an area that far pre-dates modern times.  We explored the ruins initially and found nothing of note; as such, we left it in peace.\n\nVery recently, the Hatecrest naga have occupied these ruins in alarming numbers.  At first, we considered it as the precursor for an attack.  Though that threat is still possible, we believe there might be something else going on.\n\nGo there, explore the ruins, and look for anything that stands out to you. Good luck, {name}.", completion = "Examining the gazebo reveals some interesting and unusual things in contrast to the surrounding ruins.\n\nFirst, the gazebo is clearly a more recent construction than the other objects in the ruins.  Second, the gazebo has a small series of glyphs engraved into the sides of it; the glyphs repeat in their pattern, but it otherwise is unknown in origin and meaning.  Third, the stone of the gazebo itself is warm to the touch.\n\nThis certainly quantifies as \"standing out\" in the search of the ruins!", objectives = "Explore the Ruins of Solarsal and investigate the presence of the naga there.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2867] = { id = 2867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Feathermoon Stronghold", description = "With the discovery of the strange gazebo in the heart of the Ruins of Solarsal, the time has come to return to Feathermoon Stronghold and report to General Shandris Feathermoon what has been discovered here.", completion = "Welcome back, {name}.  Your report on this gazebo is most... disturbing.  It would seem that even if the naga there were not planning on an attack, their continued presence bodes ill for our push into Feralas.  At any rate, here is compensation for your investigation.\n\nIt would seem that Feathermoon Stronghold is in dire need of additional assistance concerning the Hatecrest naga.  I'd like to offer you the task, if you are so inclined.  There is much to do.", objectives = "Return to Shandris Feathermoon in the Feathermoon Stronghold and report your findings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2869] = { id = 2869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Against the Hatecrest", description = "The best course of action at this point is to assume that, regardless of what the naga are up to, they will eventually move to secure the island for their own.  We need to take aggressive steps to counter that threat before it is too late.\n\nBring me ten Hatecrest Scales that are in good condition; it should be obvious to you how to acquire them.  You'll cut your teeth on the naga for the first time, and we'll have a weakened naga presence on Sardor Isle - both are prospects that play to our advantage.", progress = "{name}, if you're here to verify the task given to you, then excellent - it is ten Hatecrest scales I seek.  If you are here for chit-chat, then I am currently unavailable for such trivialities.\n\nKnow this - we night elves are not warmongers.  Our race is dedicated to the preservation of peace and harmony.  This does not mean, however, that we will not proactively protect our own interests.  This is my duty to General Feathermoon, and to the stronghold.", completion = "Yes, yes, these scales are more than satisfactory.  Actually, I think I will send these down to Pratt for him to take a look at.  Maybe he can craft something useful out of them.\n\nAs for you, I have another mission I want to send you on.  But first, here is your bounty for the scales.  Your continued service to the General and Feathermoon Stronghold at large is a blessing in the face of adversity.", objectives = "Bring 10 Hatecrest Naga Scales to Latronicus Moonspear in Feathermoon Stronghold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2870] = { id = 2870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Against Lord Shalzaru", description = "{name}, new scouting reports have given us a good idea on the naga chain of command.  Royalty is present amongst their rank and file, and they're the ones calling all the shots.\n\nSpecifically, we've identified one of the crueler royals as Lord Shalzaru.  Scouts report that he himself has uncovered an odd relic during a recent naga excavation in a cave south of the main ruins, across the water on the Isle of Dread.\n\nPut a stop to it by putting a stop to him, and bring me his relic so we can study it.", progress = "Bringing down Lord Shalzaru would certainly set their plans back weeks, if not months.  On top of that, the relic he uncovered is of definite interest to us.\n\nHave you performed the mission given to you, {name}?", completion = "Well played, {name}! Lord Shalzaru's demise will throw the naga into disarray for some time, if not permanently.  The threat they pose is now under more of our control than it has ever been, and we have you to thank for it.\n\nHere is more bounty money from the stronghold treasury - you've earned every copper.  You and yours are welcome in Feathermoon Stronghold anytime, my friend.\n\nOne more thing before you depart, {name}... if you could...", objectives = "Eliminate Lord Shalzaru, and then bring the Mysterious Relic he uncovered to Latronicus Moonspear in Feathermoon Stronghold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2871] = { id = 2871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delivering the Relic", description = "If you would be so kind as to deliver the relic to my wife Vestia, I would appreciate it.  She's not only a fine priestess for our community, but she is one of the most well-versed scholars you'll find anywhere.  I couldn't make heads or tails of this device even if there was a wager involved.  My wife though, if anyone can figure out what this thing is, she could... and we need to know!\n\nShe's just around the bend, no doubt studying.  Thanks, {name}.", progress = "Yes, may I assist you?\n\nHold on, you're the {class} that has been helping General Feathermoon and Latro out with the naga threat, yes?  I'm Vestia, Latro's - erm, rather, Latronicus' wife.  It is a pleasure to meet you!\n\nI'm sorry, you're here on business, of course.  Do you have something for me - from him, perchance?", completion = "Interesting... this came from the Ruins of Solarsal, you say?  Well, Latro's right that I need to look at this.  At first glance, it seems non-indigenous to the ruins.  Then again, this isn't of naga design... not something as alien as this.\n\nIt is going to take some time to research this item.  Once my research on it is done, maybe I will make use of your talents, should you be around.\n\nHere, take one of these extra items we have; I hope you'll find some use for it!", objectives = "Deliver the Mysterious Relic to Vestia Moonspear in Feathermoon Stronghold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2872] = { id = 2872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stoley's Debt", description = "My old buddy Stoley owes me a very special bottle of rum.  He tends the bar at Steamwheedle Port in Tanaris, Kalimdor,  and he promised me that the rum there is stronger than anything we can find in Booty Bay.  He's so confident that he says if I try that rum and don't agree with him, then he'll double the money he owes me!\n\nWell, I think he's not as confident as he was when last we spoke, and now he's afraid to give me that rum.  But I don't back down from wagers, so why don't you talk to him for me...", completion = "Ah, so you've been speaking with MacKinley, have you?\n\nIt's not what he thinks!  I'm not afraid to give him some Steamwheedle Bilge Rum...\n\nI just don't have any rum to give him!", objectives = "Speak with Stoley in Steamwheedle Port.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2873] = { id = 2873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stoley's Shipment", description = "I owe \"Sea Wolf\" MacKinley in Booty Bay some rum, to settle a bet, but I'm all out of rum!  Captain Cuergo stole my last shipment, and he has it stowed in that walled pirate town to the south.\n\nIf you can find my shipment of rum and return it to me, then I can prove to MacKinley that Kalimdor's booze beats the dirt out of Booty Bay!", progress = "Did you find my shipment of rum, {name}?", completion = "Great, thanks for the shipment!  Now MacKinley and I can finally settle our wager.", objectives = "Bring Stoley's Shipment to Stoley in Steamwheedle Port.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2874] = { id = 2874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deliver to MacKinley", description = "Thanks again for your help, {name}.  Here's a bottle of Steamwheedle bilge rum.  Take it to MacKinley and he can finally put to rest his crazy beliefs about Booty Bay booze.", progress = "Did Stoley cough up my booze?", completion = "Hm, let's try this...\n\nI can't believe it!  This stuff is... terrible!  That's great!\n\nWell I guess Stoley can keep the money he owes me.  He's true to his word about Steamwheedle bilge rum.  That stuff is as thick as gravel and burns like lava!", objectives = "Bring Stoley's Bottle to \"Sea Wolf\" MacKinley in Booty Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2875] = { id = 2875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Andre Firebeard", description = "The vile pirate Andre Firebeard is wanted for crimes against Steamwheedle and Gadgetzan.\n\nBy decree of governing counsel, any who read this are hereby authorized to use lethal force during the apprehension of Andre and his abettors.\n\nBy further decree, should Andre be deceased, or otherwise indisposed, during the time of his hearing, his head may act as proxy, and deliverance of such head to Security Chief Bilgewhizzle constitutes a binding, and tenderable, contract.", progress = "You look a little dazed.  Have you been reading our legal documents?", completion = "Ah, Andre's head.  So I guess he'll make his trial after all!\n\nMuch appreciated, {name}.  Now if you'll just sign here, I can issue you payment for services rendered.\n\nDon't worry about the small print.  It's harmless, and... I don't think there's a magnifying glass small enough to read it anyway.", objectives = "Bring Andre's Head to Security Chief Bilgewhizzle in Steamwheedle Port.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2876] = { id = 2876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ship Schedules", description = "This scroll contains the schedules of shipments between Steamwheedle Port and Booty Bay. Both past and future shipments are included, along with ship names, with large 'X's next to some ships' journeys, and annotations like \"GREAT LOOT\" and \"HARD FIGHT\" next to others.\n\nSomeone at Steamwheedle Port would want to see this document.", progress = "You look out of breath.  You have something to tell me?", completion = "Oh my, this looks to be a list of ship departures and arrivals, with accurate dates and times and everything!  If the captain of a pirate ship got his hands on this, he could have himself a field day!\n\nYou say you got this from a pirate?  Well that's disturbing news...\n\nThank you, {name}.  I'm glad you took it from him, and I'm glad that pirate's eating dirt right now!", objectives = "Report the Ship Schedules to an authority in Steamwheedle Port.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2877] = { id = 2877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skulk Rock Clean-up", description = "We Wildhammers remember the past, more than our brothers in Ironforge.  If you want to make friends here, then you get your hands dirty for us!\n\nThe Horde abandoned their positions in the Hinterlands around Skulk Rock; it's now overrun with nasty sludges and oozes.  We've got plans on that area, but first we need a clean-up crew to make a hole for us.\n\nThat's where you come in, Sunshine!  Head down there and take out ten green sludges and ten jade oozes, then report back to me here.  Move out!", completion = "Well look at you, helping out the Wildhammers!  You're a {class} of action, and action is what we respect around here.\n\nYour little clean-up mission is a lot more important than you might think it is.  With folks thinning out the oozes and sludges, we'll be able to extend our sphere of influence in no time. Here - have a little something in addition to just making new friends here in Aerie Peak!", objectives = "Kill 10 Green Sludges and 10 Jade Oozes, and then report back to Fraggar Thundermantle in Aerie Peak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2878] = { id = 2878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupted Songflower", progress = "You have found a sickly, corrupted version of what appears to be a songflower plant.  A pungent, unhealthy odor emanates from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply some Cenarion plant salve to the songflower.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
quests[2879] = { id = 2879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stave of Equinex", description = "This stave might be the Stave of Equinex! The Stave of Equinex is actually a key, used to unlock the Equinex Monolith in the Ruins of Ravenwind, on the mainland west of the Dream Bough.\n\nFind the four flames that still burn in those ruins: Samha, Imbel, Byltan, and Lahassa. Retrieve their essence and then while standing by the Equinex Monolith, use the essences to energize the stave. If this is truly is the Stave of Equinex, you will be able to unlock the Monolith and gather a sacred artifact from it.", progress = "The Equinex Monolith stands silently among the ruins. What could it be holding?", completion = "Holding the energized stave is almost impossible. Its power rumbles through your body.\n\nYou reach out to the cold surface of the Equinex Monolith...\n\nA small door opens, allowing you to reach in and take the artifact inside.\n\nBeams of light fill the area around the Equinex Monolith.", objectives = "Energize Troyas' Stave and find the Equinex Monolith.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2880] = { id = 2880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troll Necklace Bounty", description = "Get this straight, {race} - we are NOT part of the Alliance!  The Wildhammers are independent, relying on deeds and actions to prove one's worth, rather than the blather of those who use jibber-jabber to bolster their do-nothing attitudes!\n\nIf you're looking for friends here, then prove your worth to us first!  The foul trolls that choke the hillsides of the Hinterlands sometimes carry tribal necklaces.  Bring five of them to me, and we'll mark it down as a step in the right direction for you.", progress = "I want five of those tribal necklaces the trolls carry on them.  If you need it spelled out further, then killing one of them stands you a good chance of getting one!\n\nProve your worth to the Wildhammers!", completion = "Now that's what I am talking about!  See - these necklaces prove that you're willing to get your hands dirty.  We Wildhammers value that in those we associate with.\n\nYou keep this up, and you'll be in our good graces yet.", objectives = "Bring 5 Troll Tribal Necklaces to Fraggar Thundermantle in Aerie Peak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2881] = { id = 2881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troll Necklace Bounty" }
quests[2882] = { id = 2882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cuergo's Gold", description = "This map shows a stretch of beach with a southern face.  Below the map are words, elegantly written...\n\n\nSouth of Wheedle\nSouth of home\nFind a mast and flag and bones\nDig you there, if you be bold\nDig and claim Cuergo's gold!\nA key you'll need and a key you'll see\nThe men you face take blood as fee.", progress = "This chest is locked!", completion = "Captain Cuergo's hidden treasure awaits!", objectives = "Find Cuergo's gold!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2902] = { id = 2902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Woodpaw Investigation", description = "Gnolls aren't the sharpest tools in the shed, but they will no doubt have some sort of documented strategy on their recent activity.  If we were to find those plans, then we'd have a clearer idea of what is making them so worked up.\n\nI want you to head back to the Woodpaw and find anything that might resemble their battle plans.  They have to have something; their attacks have been too coordinated to be done without them.  Find them, and return to me when you have them.", completion = "Examining the map reveals it to be the battle plans that Hadoken Swiftstrider wants.  Numerous arrows that perhaps represent troop movements are drawn on the map, though most seem to be headed toward the south rather than to the north where Camp Mojache lies.\n\nAnother section of the map has a picture of what you think is a large insect of some kind, with various tick marks under it.  From the looks of the gnolls, it perhaps represents their losses against the unknown bugs...", objectives = "Find the gnoll battle plans somewhere in the gnoll camps to the south of Camp Mojache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2903] = { id = 2903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle Plans", description = "With the battle plans of the gnolls discovered, all that now remains is to bring the plans back to Hadoken Swiftstrider in Camp Mojache.  Perhaps he or someone there can make further sense of what the gnolls are up to.", progress = "Welcome back {name} - were you able to find some tangible evidence as to the plans of the gnolls?", completion = "Ah, this is exactly what we needed.  While I am not so skilled at ciphering what most of the scrawling on this map is, I've seen enough battle plans in my day to understand what is happening with the gnolls.  It looks like they are currently fighting a two front war.  One is with us... but it seems that their main energy has been against a foe to their south.\n\nThere's more at hand here than meets the eye.  Perhaps it is time to figure out who this other foe they face really is.", objectives = "Bring the Woodpaw Battle Plans to Hadoken Swiftstrider in Camp Mojache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2904] = { id = 2904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fine Mess", description = "<Kernobee groans.> Wha.. What happened?\n\nThe last thing I remember is being captured by a group of dark iron dwarves, beaten to within an inch of my life and then thrown in here with these filthy troggs.\n\nGet me out of here, {name}!\n\nHere's the plan: Lead me to the exit; if we make it out alive, you go to Booty Bay and let Scooty know that I went to Ratchet to warn Tinkerwiz of the dark iron's involvement in the making of that super rig.\n\nLet's get going!", completion = "I suppose you should be rewarded for bringing Kernobee back to us in one piece, {name}. If you go back to Gnomeregan, these might give you the edge you'll need in defeating that good-for-nothing backstabber, Mekgineer Thermaplugg.", objectives = "Escort Kernobee to the Clockwerk Run exit and then report to Scooty in Booty Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2922] = { id = 2922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Save Techbot's Brain!", description = "When our beloved city Gnomeregan fell, a rogue spark must have jolted my poor creation, Techbot.  It once aided me and my associates with its countless gizmos and limitless store of information, but its positronic brain has polarized.  Now it's negatronic... and Techbot's behaviors are reversed.  It roams Gnomeregan in a frenzy!\n\nBut perhaps it can be salvaged.  Perhaps, if you can retrieve Techbot's memory core and bring it to me, I can discover the cause of the polarization and fix my poor Techbot.", progress = "Did you find Techbot?  Did you retrieve its memory core??", completion = "Oh, this is wonderful!  Thank you, {name}!  I'll get to work immediately!!\n\nPoor, poor Techbot... Don't feel bad.  We'll get you fixed.\n\nNow, where did I put that plug for my hydro-jack swivel spanner...", objectives = "Bring Techbot's Memory Core to Tinkmaster Overspark in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2923] = { id = 2923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tinkmaster Overspark", description = "Tinkmaster Overspark is very upset with the fate of his mechanical creation, Techbot.  I remember Techbot as a kind and helpful tool for the gnomes, but Overspark tells me it's malfunctioned.\n\nVery sad.  But with luck perhaps he can be fixed!\n\nSpeak with Tinkmaster Overspark, in Tinker Town in Ironforge.  He would welcome your help.", completion = "Yes it's true.  Techbot has gone rogue!  Please, can you help me?", objectives = "Speak with Tinkmaster Overspark in Ironforge.Tinkmaster Overspark is very upset with the fate of his mechanical creation, Techbot. I remember Techbot as a kind and helpful tool for the gnomes, but Overspark tells me it's malfunctioned.\n\nVery sad. But with luck perhaps he can be fixed!\n\nSpeak with Tinkmaster Overspark, in Tinker Town in Ironforge. He would welcome your help.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2924] = { id = 2924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essential Artificials", description = "A nigh-universal mechanical component--the essential artificial--was of great use to the tinkers and smiths of Gnomeregan.  But during the frantic exodus from our city, no one remembered to take any of these devices with them!  And I need a large supply of them for work I will soon undertake.\n\nPlease, go into Gnomeregan and get me some essential artificials.  You'll find them in the deeper areas of our city, held in containers called artificial extrapolators.\n\nThank you, {name}, and please hurry!", progress = "Do you have the essential artificials?", completion = "You got them!  Now I can begin my new experiments!\n\nI can't thank you enough, {name}!  Your bravery has advanced gnomish research by a leap and a bound!", objectives = "Bring 12 Essential Artificials to Klockmort Spannerspan in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2925] = { id = 2925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klockmort's Essentials", description = "A gnome friend, Klockmort Spannerspan, sent word to me from Ironforge.  He tells me he needs help on a dangerous, but essential, mission into Gnomeregan, the once great gnome city now contaminated and filled with mad gnomes and their devices.\n\nI must stay here, but my heart aches to help my friend.  If you can go in my stead, then I would be much indebted to you.\n\nYou may find Klockmort in Tinkertown, in Ironforge.", completion = "I do!  I do need help with a mission into Gnomeregan.  And you're just the {class} to do it!", objectives = "Speak with Klockmort Spannerspan in Ironforge.A gnome friend, Klockmort Spannerspan, sent word to me from Ironforge. He tells me he needs help on a dangerous, but essential, mission into Gnomeregan, the once great gnome city now contaminated and filled with mad gnomes and their devices.\n\nI must stay here, but my heart aches to help my friend. If you can go in my stead, then I would be much indebted to you.\n\nYou may find Klockmort in Tinkertown, in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2926] = { id = 2926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnogaine", description = "Since the accident, all Gnoarn thinks about or talks about is cleansing Gnomeregan of the trogg infestation and finding a cure for the sickness that plagues it, {name}.\n\nLuckily, Razzle and I are close to some kind of cure - either that or the recipe for a really powerful rum. We won't know until we test! Naturally, in order to test our theory, we're going to need a few things; namely, fallout from the irradiated troggs in Gnomeregan. Fill up this phial with the green glow and bring it back!", progress = "Can't you see we're trying to cure an entire species of gnomes here??! We need more of the green glow!", completion = "Excellent work! The time has come to test the new formula. If this works, not only should that captured leper gnome be cured, but I should have a full head of hair! Stand back!", objectives = "Use the Empty Leaden Collection Phial on Irradiated Invaders or Irradiated Pillagers to collect radioactive fallout. Once it is full, take it back to Ozzie Togglevolt in Kharanos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2927] = { id = 2927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Day After", description = "You don't think I was always bald, do you? No <sir/ma'am>! It was the radiation leak in Gnomeregan that caused this tragic hair loss. Before that day, I had the only gnomefro in all of Azeroth.\n\n<Gnoarn shakes his fist in the air.>\n\nDamn those damned dirty troggs - damn them all!!\n\nPerhaps it's not too late, {name}. We may still be able to save it - the city I mean! Speak to Ozzie Togglevolt in Kharanos. He and his partner Razzle are working on a solution.", sourceObjective = "Speak with Ozzie Togglevolt at Kharanos in Dun Morogh.", completion = "I thought the loss of that outstanding head of hair would have been the end of him for sure, but he survived!\n\nI was standing right next to him when he was hit by the radiation bolt. Those delightful brown locks of hair hit the floor in clumps! Clusters! The horror of it all was only compounded when Gnoarn completely freaked out! Oh yes, freaked out I say! Gnoarn touched his bald head in disbelief, the look in his eyes screamed revenge, {name}! Then he turned his anger towards the troggs!", sourceObjectiveStatus = "unverified-source-field" }
quests[2928] = { id = 2928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gyrodrillmatic Excavationators", description = "It's terrible, {name}. We are not going to have enough parts to get our fleet of gyrodrillmatic excavationators to Dun Morogh.\n\nWhat we need are spare parts, {name}. What better place to get the spare parts for our vehicles than Gnomeregan? I hear that bots and mechs roam around that place like cattle on an open range.\n\nWhat I need you to do is go to Gnomeregan and tear apart those robots. Bring me back their robot guts. Two dozen should be sufficient.", progress = "If this were a race, you would have lost by now.", completion = "This will do nicely, {name}. One gyrodrillmatic excavationator fixed; 398 left to go.", objectives = "Bring twenty-four Robo-mechanical Guts to Shoni in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2929] = { id = 2929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grand Betrayal", description = "I trusted Thermaplugg, {race}. Never did I expect that he would betray me and the entire gnomish people. And for what? Power? Wealth? All things that he would have had in time. Now we have been displaced from our home and that madman is in charge. The king of nothing....\n\nWe will retake Gnomeregan, {name}. We will not stop until the city is back in our control. If you wish to join in our fight, a simple task I ask of you: Kill the betrayer. Destroy Mekgineer Thermaplugg.", completion = "I like to think that the last thing that went through his head as he collapsed to the ground was your foot, {race}. With Thermaplugg dead, our plans to retake Gnomeregan are one step closer to becoming a reality.", objectives = "Venture to Gnomeregan and kill Mekgineer Thermaplugg. Return to High Tinker Mekkatorque when the task is complete.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2930] = { id = 2930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Data Rescue", description = "When we fled Gnomeregan, we left so much data behind!  Vitally important data!\n\nI need the data on a prismatic punch card, from a Matrix Punchograph 3005-D high security terminal, deep in Gnomeregan.  You must access the terminal, but to do that you first need clearance... and to get that you must access lower security terminals-- models -A, -B and -C.  And to do THAT you need security punch cards, starting with white... and we left all the punch cards in the city.\n\nIt's a catastrophe!  Can you help?", progress = "Do you have the prismatic punch card??", completion = "You did it!  You found the prismatic punch card and recovered the lost data!  Vitally, critically, immeasurably important data that we could not live another moment without!\n\nYour service to the gnomes will be long remembered, {name}.", objectives = "Bring a Prismatic Punch Card to Master Mechanic Castpipe in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2931] = { id = 2931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Castpipe's Task", description = "Master Mechanic Castpipe in Ironforge has need of adventurers!  He's organizing bands to reenter Gnomeregan on a data retrieval mission of top security and importance.\n\nCastpipe might not be a member of the Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences like I am, but he's still a smart gnome so if he thinks it's important, then by my calculations there's an eighty-four percent probability that it really is important!\n\nThose are good odds!", sourceObjective = "Speak with Master Mechanic Castpipe in Ironforge.", completion = "I'm organizing data extraction missions into Gnomeregan.  If you're here for that, then listen up!", sourceObjectiveStatus = "unverified-source-field" }
quests[2932] = { id = 2932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grim Message", description = "The Witherbark trolls were once allies to the Horde, but they betrayed Thrall... and that must be punished!\n\nHere, take my pike and go to the Hinterlands, far to the north.  You will find it northeast of Tarren Mill, a village held by our allies, the Forsaken.\n\nWhen you enter the Hinterlands, hunt Witherbark trolls.  Gather their skulls and drive my pike into the ground at one of their smaller villages, Hiri'watha or Zun'watha.\n\nShow them their vile actions are of consequence!", completion = "Word reached me of your deed.  A grim deed, but one of honor.  Let us hope the Witherbarks heed your message.", objectives = "Gather Witherbark Skulls and place on Nimboya's Pike. Place Nimboya's Laden Pike at one of the Witherbark Villages in the Hinterlands, then return to Nimboya in Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2933] = { id = 2933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venom Bottles", description = "These bottles hold a vile, green venom.\n\nConsidering the number of bottles in this village, the Witherbarks must deem it very important.  Perhaps an apothecary in nearby Tarren Mill would like a sample.", progress = "Hello, gentle {class}.  The day has been long and not a single experiment successful...I hope you bring good news to me.", completion = "Ah, and what is this?  It appears to be venom... from some arachnoid creature I deem.  And where did you get it?", objectives = "Bring a Venom Bottle to an apothecary in Tarren Mill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2934] = { id = 2934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Undamaged Venom Sac", description = "I must have a fresh sample of the venom you brought me.  The spiders from which it was gathered must dwell in the Hinterlands -- hunt them until you find an undamaged venom sac and bring it to me.  You will find many spiders near the troll city of Shadra'Alor.\n\nDo not tarry, {name}, for the venom sac must be fresh when you deliver it.", progress = "Do you have the undamaged venom sac, {name}?  I yearn to run experiments with its fresh venom, and have ordered a collection of small, terribly cute animals on which to test it!", completion = "Oh, splendid!  The venom is quite fresh and I'm sure very deadly.  Thank you!", objectives = "Bring an Undamaged Venom Sac to Apothecary Lydon in Tarren Mill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2935] = { id = 2935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Consult Master Gadrin", description = "The venom from the broodguards wasn't as potent as the venom you brought originally.  It must have come from a different spider.\n\nI want a fresh sample of that venom.  To find out where it came from, you must consult with a troll who knows the Witherbark well--Master Gadrin in Sen'jin Village.  Travel to Durotar and speak with Gadrin.  With luck, he'll know where the Witherbarks get their venom.", completion = "Ah, so you want fresh venom from the spider of the witherbarks, yes?  Well, sit down... you're not going to like what I have to tell you.", objectives = "Speak with Master Gadrin in Sen'jin Village.The venom from the broodguards wasn't as potent as the venom you brought originally. It must have come from a different spider.\n\nI want a fresh sample of that venom. To find out where it came from, you must consult with a troll who knows the Witherbark well--Master Gadrin in Sen'jin Village. Travel to Durotar and speak with Gadrin. With luck, he'll know where the Witherbarks get their venom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2936] = { id = 2936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spider God", description = "The Witherbarks worship a spider god, and from her they collect their most potent venom.  So if you want the venom, then you must summon their god!\n\nTo do that, you must know her true name, and that name is on a tablet buried in Tanaris, in the troll city of Zul'Farrak, in a tomb guarded by Theka the Martyr.\n\nDefeat Theka and find and read his tablet to discover the spider god's name.  When you know it, return to me.", completion = "Ah, Elortha no Shadra... speak this name only in whispers, for its utterance carries much weight in the realms of the spirit.\n\nI will put it to parchment and create for you a spell of summoning...", objectives = "Read from the Tablet of Theka to learn the name of the Witherbark spider god, then return to Master Gadrin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2937] = { id = 2937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Summoning Shadra", description = "Take his parchment, and read it at the altar of Shadra'Alor, deep within the witherbark realm in the Hinterlands.  This will summon Shadra the spider god.", progress = "Did you get the venom?", completion = "Sweet, you got it!", objectives = "Defeat Shadra at the altar of Shadra'Alor, then bring her venom to Apothecary Lydon in Tarren Mill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2938] = { id = 2938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venom to the Undercity", description = "The venom you gathered from the Witherbark's spider god is quite a find!  I've been able to kill nearly two dozen rabbits with just a drop of the stuff.  Granted, some of those rabbits were very young and small enough to fit in the palm of one's hand so I'm certain their resistance to toxins was low, but it can't be denied that this poison is powerful!\n\nI'd like a sample sent to my superior, Apothecary Faranell in the Apothecarium of the Undercity.  I am positive he would want to test this himself.", progress = "Word was sent of your coming, {name}.  You have a parcel for me?", completion = "Ah, very good.  Lydon mentioned the poison in this parcel is the most potent he has come in contact with, and is busy working on new applications with it.\n\nWith luck, we will find many.\n\nThank you, {name}.  Your service to the Royal Apothecary Society is undeniable.", objectives = "Bring Faranell's Parcel to Master Apothecary Faranell in the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2939] = { id = 2939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search of Knowledge", description = "While the ruins of Feralas can be quite dangerous, they have much to tell of what has happened here.\n\nSearching through the rubble to the south a few days ago, I discovered what appears to be a normal stave. However, I just can't shake the feeling that there is something more to it. Angelas and I have been poring over our books here, but we can't find a thing about it.\n\nI have a colleague in Darnassus that may be able to tell us what this is, {name}. Why don't you go talk to her and see if she can help us?", sourceObjective = "Talk to Daryn Lightwind in Rut'theran Village.", completion = "Oh, so Troyas Moonbreeze sent you?\n\n<mutters>...always bothering me with his wild notions that he found something important...\n\nLook, {name}, I'll be blunt. Troyas always thinks he has found something important in those ruins. The truth is, anything that was truly valuable was probably hoarded away long ago by the ogres or the harpies that now reside there.\n\nYou're welcome to take a look around, but I don't know if you'll find any books here that will help you.", sourceObjectiveStatus = "unverified-source-field" }
quests[2940] = { id = 2940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feralas: A History", description = "This book looks as if no one has opened it for quite a long time. Its covers are quite worn, and its pages yellowed, but after examining it, you notice that it might be just what Troyas is looking for.\n\nYou pick it up, but realize you should probably ask before borrowing it.", sourceObjective = "Ask Daryn Lightwind if you may borrow her book.", completion = "So, you'd like to borrow Feralas: A History?\n\nLet me think...\n\nI will allow you to borrow this book, {name}, but only if you do something for me first.", sourceObjectiveStatus = "unverified-source-field" }
quests[2941] = { id = 2941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Borrower", description = "I have studied many subjects in my time, and my latest fascination is with the snapjaw that occupy the beach in the Hinterlands. There's one in particular I'd like to see, a giant snapjaw named Gammerita. I'd like to go myself, but my research keeps me here. I think a picture of her would be the next best thing.\n\nTake this letter to Curgle Cranklehop in Tanaris. She has created an invention for me that can capture a picture. She called it a \"snapshot,\" I think...", progress = "A letter -- for me?", completion = "Are you another one of Daryn's interns? She's quite a knowledgeable historian, {name}. You should be grateful to be studying under her leadership.\n\nNow, let me get the Super Snapper FX. You're gonna love it!", objectives = "Take the letter to Curgle Cranklehop in Tanaris.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2942] = { id = 2942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Morrow Stone", description = "The moment the artifact is removed from the Monolith, you feel the energy in the Stave of Equinex begin to fade.", progress = "I am glad you have returned, {name}. I am eager to hear of your findings.", completion = "I have been reading since you left, {name}. This stone you have found is called the Morrow Stone. While I am not entirely sure what its purpose is yet, you can be sure that it is something of great significance to be hidden away inside the Equinex Monolith the way it was.\n\nI will continue my studies, and I hope I will be able to count on you in the future, {name}. Thank you for all your help.", objectives = "Return the Sparkling Stone and the Stave of Equinex to Troyas Moonbreeze in Feathermoon Stronghold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2943] = { id = 2943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Troyas", description = "Here it is, {name}. Please, take care of my book.\n\nNow, hurry along. I'm sure Troyas is eager for your return.", progress = "Hello, {name}. Have you been to Darnassus?", completion = "You have brought a book along. Excellent!", objectives = "Deliver the book to Troyas Moonbreeze in Feathermoon Stronghold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2944] = { id = 2944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Super Snapper FX", description = "Have the first look at my new invention, {name}. All you need to do is target whatever it is you'd like to take a picture of, and push the button.\n\nWhat was that creature from the Hinterlands that you mentioned? Gammerita? Well, good luck finding her. I'm sure Daryn will be quite pleased with the snapshot you return to her.\n\nIn any case, here's the Super Snapper. Have fun!", progress = "So, you have finally returned, {name}. And you've brought the contraption that Curgle built for me -- perfect.", completion = "Well! Curgle's invention lived up to its expectations.\n\nDon't get too excited, but do know that I am pleased with your work, {name}.\n\nNow, where did I leave that book...", objectives = "Use the Super Snapper FX to take a snapshot of Gammerita, then return to Daryn Lightwind in Rut'theran Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2945] = { id = 2945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grime-Encrusted Ring", description = "You have uncovered what appears to be a ring from the corpse of one of the Dark Iron dwarves.  It is difficult to tell what kind of ring it is, however; dirt and hardened residue cake the item completely, making wearing it impossible.  You think you can make out the slight luster of precious metal and maybe even the glint of a gem under the residue.\n\nIf you are going to make use of this ring, you are going to need to find something to get the hardened residue off of it.", progress = "The gnomish contraption before you bears a plaque calling it \"The Sparklematic 5200\".  The gist of the machine, from reading the instructions below the plaque, is to scrub away dirt that an item might have.  The machine has a coin slot, accepting three silver coins to start the process once the item is placed inside it.\n\nIt would seem as though the grime-encrusted ring you found earlier is just the thing to try in this machine!", completion = "You place the ring inside the Sparklematic 5200 and deposit a silver coin into the slot.\n\nPainful grinding noises emanate from the machine as it begins to jerk around violently.  One can only guess what is happening with the ring inside the machine...\n\nThe machine suddenly stops, trumpeting its cessation with a simple \"Ding!\"  The item receptacle opens up to reveal a small box that is neatly wrapped with a red bow.  It would appear that the Sparklematic 5200 also gift wraps!", objectives = "Figure out a way to remove the grime from the Grime-Encrusted Ring.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2946] = { id = 2946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeing What Happens", description = "We want you to take the miniature discs you found to the sealed gates of Uldum.  We... we aren't sure what will happen when you do this.\n\nThis sounds risky, sure, we acknowledge that.  It might, however, do nothing.  You might need to use the discs on something.  Perhaps the doors unlock when you have the discs in your possession.  Be open to try anything, and be ready for anything to happen.\n\nWhen you've found out what happens, return to Ironforge.  We'll have a lot to analyze when you're done!", progress = "This familiar looking pedestal sticks out of the hot sand.  Perhaps there is something to its presence here...", completion = "As you touch the pedestal, the miniature discs from Uldaman hum and glow in your backpack.  A familiar feeling tingle washes over your hands, as the image of another Stone Watcher springs to life in front of the gates of Uldum.\n\n\"Salutations.  I am a guardian of entry.  The discs that have been used for access are missing the correct entry discs, the Plates of Uldum.  Please incorporate these plates with the disc structure and repeat your access sequencing.  Thank you.\"", objectives = "Bring the miniature platinum discs to the gates of Uldum in Tanaris and look for clues as to the connection between the two.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2947] = { id = 2947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return of the Ring", description = "Opening the box produced by the Sparklematic 5200 reveals what you had suspected - a shiny ring!  Wearing the ring, you feel magic power surge through you body.\n\nInside the band is a small but nonetheless discernable imprint of the seal of Ironforge.  Next to that, three small initials are engraved: \"TdK\".  This may signify either the initials of the previous owner, or perhaps the initials of the ring's crafter.  Keep the ring... or return it to this person.  Decisions, decisions...", progress = "Hey, easy there partner - I'm a very important businessman!  I am sure that the courier is just simply late with the delivery of the rent... wait... you're not my landlord.\n\nWell, of course you aren't - silly me!  You've come to me seeking the finest jeweler in all of Ironforge, one who does NOT make CURSED items!  Yes!\n\nUm... what do you need?", completion = "A ring, you say?  Let's see... yep, I made that ring by golly.\n\nBefore Gnomeregan went up, I had a small shop there.  Perhaps it's one I left behind when I ran for the hills; it's a simple design, and I made several like it.  Maybe it's from someone who didn't make it out.\n\nDark Iron dwarves had this?  Well, that puts a new layer of conspiracy on the nine different layers already floating about.  Maybe the authorities would like to know; it's wasted on the likes of me.\n\nNow, back to the ring...", objectives = "You may either keep the ring, or you may find the person responsible for the imprint and engravings on the inside of the band.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2948] = { id = 2948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnome Improvement", description = "Listen {name}, that ring is yours, sure... but I can make you a better one!  That design, like I said, is really simple.  I am a lot more skilled now, and for the mere fee of thirty silver coins I'll spruce it up for you!  Well, a little more than thirty, actually...\n\nI'm in a tight spot right now; all my material stock is all dried up.  If you bring me a bar of silver and a moss agate, I'll add a silver and agate lattice to the ring that will give it a little more pizzazz!\n\nTrust me!", progress = "Do you have the materials I need?  I wouldn't ask you for them if I wasn't down on my luck...", completion = "Ah, exactly what I needed!  Someday, when I find myself out of this hole that I am unjustly in, I will make for you, for EVERYONE the finest trinkets in all of Azeroth!  Until then, thanks for being a sport about the reagents.  I'd normally charge ten times what I have charged you for a ring of this quality...\n\nSpeaking of rings, here's your new one!", objectives = "Bring the Brilliant Gold Ring, a Silver Bar, a Moss Agate, and 30 silver coins to Talvash del Kissel in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2949] = { id = 2949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return of the Ring", description = "Opening the box produced by the Sparklematic 5200 reveals a shiny ring!  Donning the ring, you feel magic power surge through your body.\n\nInside the band is a small but nonetheless discernable imprint of the seal of Orgrimmar.  Engraved letters are next to it, but only the first three stand out even after cleaning: \"NOG...\"\n\nThis may signify either the initials of the previous owner, or perhaps the initials of the ring's crafter.  Keep the ring... or find \"NOG\" - decisions, decisions...", progress = "You'd think that we would find a way on our own to outdo those filthy little gnomes.  I would even wager that they stole that rig from us to begin with!  Bah, those greasy, grimy... erm, yes?  You need something?", completion = "A ring from Gnomeregan?  Let's see... not mine, but interesting.\n\nThe Gnomeregan thing - couldn't have happened to a nicer bunch of numbskulls.  For years they're a joke, and now almost overnight they're making better rigs than us?\n\nDark Iron dwarves had the ring?  That's even more interesting!  You know, maybe the gnomes stole their crazy golem plans and modified them.  Those Dark Irons, they'd definitely want some major payback.  It's certainly worth investigating.\n\nYou know, about that ring...", objectives = "You may either keep the ring, or you may find the person responsible for the imprint and engravings on the inside of the band.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2950] = { id = 2950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nogg's Ring Redo", description = "No, no, no - I'm not all of the sudden saying that the ring is mine.  I normally don't do this, but your information about the Dark Irons was very useful.  I'll improve your ring for you, better than whomever made this simple little thing could have ever done.  Probably some gnome...\n\nIf you bring me a bar of silver, a moss agate, and thirty silver coins for my trouble, I'll add a silver and agate lattice to the ring that will strengthen the magic inside of it.  Interested?", progress = "Do you have the materials I need?  I can't improve on this design without everything I asked for.", completion = "Here's your ring, better than before.  Thanks again for the information about those Dark Iron dwarves.  This seems like a reasonable lead as to how those gnomes suddenly were struck with goblin-like inspiration.", objectives = "Bring the Brilliant Gold Ring, a Silver Bar, a Moss Agate, and 30 silver coins to Nogg in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2951] = { id = 2951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sparklematic 5200!", description = "This contraption stands out amongst the gnomes holding out against the madness outside the room.  A small plaque on the device reads \"The Sparklematic 5200\", followed by some text:\n\n\"Grime and residue ruining your sparklies?  The Sparklematic 5200 puts the shine back in shine-tastic!  Insert the item you wish to clean and deposit three silver coins in the coin slot.  Give The Sparklematic 5200 a moment for operation, and voila!  Your valuables will emerge clean and shiny!\"", progress = "It would seem that the device needs some sort of grime-encrusted object to clean and three silver coins to get the contraption working.  So long as both are present, the Sparklematic 5200 should work...", completion = "You insert the grime-encrusted item and three silver coins into the Sparklematic 5200.  The machine surges to life in an almost frenzied attempt to purge the grime from the unknown item.  Loud, violent churning sounds beat from the heart of the machine.  The metal frame of the beast creaks and groans as it lurches from side to side...", objectives = "Insert a Grime-Encrusted Item into the Sparklematic 5200, and be sure to have three silver coins to start the machine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2952] = { id = 2952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sparklematic 5200!", objectives = "As quickly as it started, the Sparklematic 5200 comes to an abrupt halt.  A simple \"ding\" is heard from the machine, and the mouth of the machine spirals upward.  Inside the Sparklematic 5200 is a small box wrapped in a little bow.  The machine would appear to wrap an object up after eliminating its grime-encrusted status.  Even if the machine didn't work, at least the item is now wrapped in a pretty box.\n\nWell, there is one way to find out if it cleaned the item or not...", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2953] = { id = 2953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Sparklematic Action", progress = "The Sparklematic 5200 is empty, awaiting a grime-encrusted object to clean and three silver coins to start!", completion = "The Sparklematic 5200 comes to life, lurching to and fro.  Inside, the helpless grime that has encrusted the object placed within it is being pulverized by the machine's gnomish cleaning agent.\n\nThe Sparklematic 5200 comes to a halt, heralded by a familiar \"ding!\"  The item receptacle of the machine spirals open, revealing a neatly wrapped box." }
quests[2954] = { id = 2954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stone Watcher", description = "\"Salutations - I am a guardian of entry.  Unless you have the Plates of Uldum already integrated with your disc set, I will not allow for entry into the Uldum compound.\"\n\nThe appearance of the Stone Watcher of Norgannon must be the reaction that was hoped for in sending you out to the Tanaris desert with the platinum discs.  As instructed, you will need to find out what the story behind the Stone Watcher is before continuing on.", completion = "The stone watcher's voice resonates with power and authority:\n\n\"Your discs will be returned to you once you access the pedestal.  When you have obtained the Plates of Uldum and incorporated them into your existing disc set, you may then enter the complex.\"", objectives = "Learn the purpose of the Stone Watcher of Norgannon, and then interact with the Uldum Pedestal in the Tanaris desert.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2962] = { id = 2962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Only Cure is More Green Glow", description = "Not only was your sample insufficient in quantity, it was also impure.\n\nWhat we require is more green glow. The troggs are obviously not irradiated sufficiently to fulfill our needs. You will have to go into Gnomeregan and bring back some radioactive fallout, straight from the tap. I am speaking of the irradiated slimes, lurkers and horrors. Be warned, the containment of this type of fallout is difficult. You may need to make several attempts with the phial until a suitable sampling is recovered.", progress = "Hrm, you're not glowing. That's a good sign.", completion = "<Ozzie examines you.> Impressive, you still have all of your limbs. Now it's time to see what this stuff can do!", objectives = "Travel to Gnomeregan and bring back High Potency Radioactive Fallout. Be warned, the fallout is unstable and will collapse rather quickly.\n\nOzzie will also require your Heavy Leaden Collection Phial when the task is complete.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2963] = { id = 2963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Portents of Uldum", description = "Greetings once again, {name}!  Your discovery inside Uldaman has set the Explorers' League abuzz with excitement.  The League has been working to unlock the secrets of the miniature platinum discs you found.  Your fortuitous arrival here in the Hall allows me to share with you that we are quite possibly on to something!\n\nHistorian Karnik has uncovered some important clues as to the true origins of the Valley of the Watchers in the Tanaris desert.  He would like to speak with you as soon as possible!", completion = "I am glad you're maintaining your interest in exploration, {name}!  With your natural talent and moxie, we could crack open secrets that we never thought were possible!\n\nThe Discs of Norgannon in Uldaman were a repository of vast information; you were only permitted to access the top layers, as it were, of the information stored there.  The Creators were rumored to have more repositories located throughout Azeroth.  This now brings us to Uldum...", objectives = "Speak with Historian Karnik in the Hall of Explorers within Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2964] = { id = 2964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Future Task", description = "Well {name}... we seem to be at a temporary dead end here.  We know what we need - the Plates of Uldum - but we have no idea where they might be.  We'll need to do quite a bit of research on this to come up with a solid plan of attack.  I have a couple ideas where to start looking; I have high hopes that soon, we'll be asking you to head out and recover them.\n\nThe High Explorer needs to be informed on this, {name}; no doubt, he also wants to thank you personally for once again aiding the League.", completion = "We're all in agreement then - the best plan of attack is putting this on hold until we can narrow down the areas where these plates might lie hidden.  You've brought us this far {name}, and I hope you will be the one to head back in to the field to unlock Uldum for us all!\n\nAllow me to give you this honorarium in the meantime; this should cover any expenses you've encountered in assisting us, and a little something extra.  Be sure to check back with us soon... Uldum beckons!", objectives = "Speak with High Explorer Magellas in Ironforge.Well {name}... we seem to be at a temporary dead end here. We know what we need - the Plates of Uldum - but we have no idea where they might be. We'll need to do quite a bit of research on this to come up with a solid plan of attack. I have a couple ideas where to start looking; I have high hopes that soon, we'll be asking you to head out and recover them.\n\nThe High Explorer needs to be informed on this, {name}; no doubt, he also wants to thank you personally for once again aiding the League.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
